BOOK_DATA = [{'page_no': 1, 'title': 'Professor Lidenbrock and the Ancient Manuscript', 'tr_title': "Hamburg'da Profesör Otto Lidenbrock ve Eski Rünik El Yazması", 'vocab_focus': [('mineralogy', 'mineraloji, maden bilimi'), ('manuscript', 'el yazması eser'), ('impatient', 'sabırsız, aceleci'), ('parchment', 'parşömen kağıdı'), ('eccentric', 'sıra dışı, tuhaf, eksantrik'), ('curiosity', 'merak, ilgi'), ('enthusiasm', 'büyük heves, coşku'), ('distinguished', 'seçkin, saygın')], 'sentences': [{'id': 1, 'text': 'On the twenty-fourth of May, 1863, my uncle, Professor Otto Lidenbrock, rushed into his little house in Hamburg.', 'translation': "24 Mayıs 1863'te amcam Profesör Otto Lidenbrock, Hamburg'daki küçük evine telaşla koşarak girdi.", 'notes': 'rushed into: telaşla koşarak içeri girdi.'}, {'id': 2, 'text': 'He was a distinguished professor of mineralogy, known for his vast knowledge and terrible impatience.', 'translation': 'Engin bilgisi ve korkunç sabırsızlığıyla tanınan seçkin bir mineraloji profesörüydü.', 'notes': 'distinguished professor: seçkin profesör.'}, {'id': 3, 'text': 'Whenever he gave lectures at the university, he spoke so fast that students could hardly follow his words.', 'translation': 'Üniversitede ne zaman ders verse o kadar hızlı konuşurdu ki öğrenciler sözlerini güçlükle takip edebilirdi.', 'notes': 'could hardly follow: neredeyse hiç takip edemezdi / güçlükle izlerdi.'}, {'id': 4, 'text': 'I lived with him as his assistant and nephew, helping him classify his immense collection of rocks.', 'translation': 'Onun yeğeni ve asistanı olarak birlikte yaşıyor, devasa kaya koleksiyonunu sınıflandırmasına yardım ediyordum.', 'notes': 'immense collection: devasa koleksiyon.'}, {'id': 5, 'text': 'On that particular afternoon, my uncle was waving an old book with tremendous excitement.', 'translation': 'O özel öğleden sonrasında amcam, muazzam bir heyecanla eski bir kitabı sallıyordu.', 'notes': 'tremendous excitement: muazzam bir heyecan.'}, {'id': 6, 'text': '"Axel, come here immediately and look at this priceless treasure!" he cried out loudly.', 'translation': '"Axel, derhal buraya gel ve şu paha biçilmez hazineye bak!" diye bağırdı yüksek sesle.', 'notes': 'priceless treasure: paha biçilmez hazine.'}, {'id': 7, 'text': 'The book was bound in rough leather and smelled of centuries of dust and damp cellars.', 'translation': 'Kitap kaba bir deriyle ciltlenmişti ve yüzyılların tozunu ve nemli mahzen kokusunu taşıyordu.', 'notes': 'bound in rough leather: kaba deriyle ciltlenmiş.'}, {'id': 8, 'text': '"I bought it from an old bookseller who had no idea of its true value," the professor explained proudly.', 'translation': '"Onu gerçek değerinden habersiz olan yaşlı bir sahaftan satın aldım," diye gururla açıkladı profesör.', 'notes': 'had no idea of: ...den tamamen habersizdi.'}, {'id': 9, 'text': 'It was an ancient Icelandic saga written in the twelfth century by Snorri Sturluson.', 'translation': 'On ikinci yüzyılda Snorri Sturluson tarafından kaleme alınmış kadim bir İzlanda destanıydı.', 'notes': 'written in the twelfth century: on ikinci yüzyılda yazılmış.'}, {'id': 10, 'text': 'My uncle opened the yellowed pages carefully, admiring the strange runic characters inscribed upon them.', 'translation': 'Amcam sararmış sayfaları dikkatle açtı ve üzerlerine kazınmış garip rünik karakterlere hayranlıkla baktı.', 'notes': 'runic characters: rünik harfler / yazılar.'}, {'id': 11, 'text': 'Suddenly, a folded piece of parchment slipped from between the pages and fell to the floor.', 'translation': 'Aniden sayfaların arasından katlanmış bir parşömen parçası kaydı ve yere düştü.', 'notes': 'slipped from: arasından kayıp düştü.'}, {'id': 12, 'text': 'I quickly bent down and picked it up before the professor could scold me for hesitating.', 'translation': 'Profesör beni tereddüt ettiğim için azarlamadan önce hızla eğilip onu yerden aldım.', 'notes': 'bent down: eğildi.'}, {'id': 13, 'text': 'The parchment was covered with mysterious letters that appeared completely incomprehensible to my eyes.', 'translation': 'Parşömen, gözlerime tamamen anlaşılmaz görünen gizemli harflerle kaplıydı.', 'notes': 'completely incomprehensible: tamamen anlaşılmaz.'}, {'id': 14, 'text': 'Professor Lidenbrock snatched the paper from my hand and examined it through his magnifying glass.', 'translation': 'Profesör Lidenbrock kağıdı elimden kaptı ve büyüteciyle dikkatle inceledi.', 'notes': 'snatched the paper: kağıdı çekip aldı / kaptı.'}, {'id': 15, 'text': '"These are runes!" he exclaimed, his dark eyes sparkling behind his thick spectacles.', 'translation': 'Kalın gözlüklerinin ardından koyu renk gözleri parıldayarak, "Bunlar rün harfleri!" diye haykırdı.', 'notes': 'sparkling behind spectacles: gözlüklerin arkasında parıldayan.'}, {'id': 16, 'text': '"Runic writing was used in ancient Scandinavia before the Latin alphabet was introduced."', 'translation': '"Rün yazısı, Latin alfabesi gelmeden önce kadim İskandinavya\'da kullanılıyordu."', 'notes': 'was introduced: getirilmişti / tanıtılmıştı.'}, {'id': 17, 'text': 'However, after a few minutes of intense study, his forehead wrinkled in deep frustration.', 'translation': 'Ancak birkaç dakikalık yoğun incelemenin ardından alnı derin bir hayal kırıklığıyla kırıştı.', 'notes': 'wrinkled in deep frustration: derin bir hüsranla kırıştı.'}, {'id': 18, 'text': 'The characters were indeed runic, but they formed a secret cipher that made no sense at all.', 'translation': 'Karakterler gerçekten rünikti fakat hiçbir anlam ifade etmeyen gizli bir şifre oluşturuyorlardı.', 'notes': 'secret cipher: gizli şifre / kriptogram.'}, {'id': 19, 'text': '"It is a cryptogram, Axel!" he shouted, pacing back and forth across the study room.', 'translation': 'Çalışma odasında bir ileri bir geri volta atarak, "Bu bir kriptogram, Axel!" diye bağırdı.', 'notes': 'pacing back and forth: bir ileri bir geri adımlamak.'}, {'id': 20, 'text': '"Someone has concealed a profound secret within this text, and I shall not rest until I unlock it!"', 'translation': '"Birisi bu metnin içine derin bir sır gizlemiş ve ben onu çözene kadar asla dinlenmeyeceğim!"', 'notes': 'shall not rest until: ...e kadar asla huzur bulmayacağım.'}]}, {'page_no': 2, 'title': 'The Cipher of Arne Saknussemm', 'tr_title': "Şifreli Parşömen: İzlandalı Simyacı Arne Saknussemm'in Mesajı", 'vocab_focus': [('alchemist', 'simyacı'), ('cipher', 'şifre, kripto'), ('signature', 'imza'), ('reveal', 'ortaya çıkarmak, açığa vurmak'), ('solution', 'çözüm, yanıt'), ('frantic', 'çılgına dönmüş, telaşlı'), ('starvation', 'açlık, açlıktan ölme tehlikesi'), ('stubborn', 'inatçı, dik başlı')], 'sentences': [{'id': 21, 'text': 'My uncle examined the lower edge of the parchment where a tiny line of faded ink was visible.', 'translation': 'Amcam, parşömenin soluk mürekkeple yazılmış küçük bir satırın göründüğü alt kenarını inceledi.', 'notes': 'lower edge: alt kenar.'}, {'id': 22, 'text': '"Arne Saknussemm!" he gasped in utter astonishment, recognizing the famous sixteenth-century name.', 'translation': 'On altıncı yüzyılın o ünlü ismini tanıyarak tam bir şaşkınlık içinde, "Arne Saknussemm!" diye nefesini tuttu.', 'notes': 'gasped in utter astonishment: tam bir şaşkınlıkla nefesi kesildi.'}, {'id': 23, 'text': '"Saknussemm was a celebrated Icelandic alchemist and a man of immense scientific daring!"', 'translation': '"Saknussemm, ünlü bir İzlandalı simyacı ve muazzam bilimsel cesarete sahip bir adamdı!"', 'notes': 'scientific daring: bilimsel cesaret / cüret.'}, {'id': 24, 'text': '"He was persecuted for heresy, and many of his writings were publicly burned after his death."', 'translation': '"Sapkınlıkla suçlanıp zulüm gördü ve yazılarının birçoğu ölümünden sonra halkın önünde yakıldı."', 'notes': 'persecuted for heresy: sapkınlıkla suçlanıp eziyet gördü.'}, {'id': 25, 'text': "The discovery of this signature transformed my uncle's scientific curiosity into pure obsession.", 'translation': 'Bu imzanın keşfi amcamın bilimsel merakını saf bir saplantıya dönüştürdü.', 'notes': 'pure obsession: saf bir takıntı / saplantı.'}, {'id': 26, 'text': 'He immediately locked the front door and decreed that no one in the house would eat until the cipher was solved.', 'translation': 'Derhal sokak kapısını kilitledi ve şifre çözülene kadar evdeki hiç kimsenin yemek yemeyeceğini buyurdu.', 'notes': 'decreed that: ...diye ferman verdi / hükmetti.'}, {'id': 27, 'text': 'Our faithful housekeeper, Martha, was horrified because she had already prepared a wonderful dinner.', 'translation': 'Sadık kahyamız Martha dehşete düşmüştü çünkü çoktan harika bir akşam yemeği hazırlamıştı.', 'notes': 'faithful housekeeper: sadık hizmetçi / kahya.'}, {'id': 28, 'text': '"No food and no sleep!" the professor barked, slamming his fist onto the wooden desk.', 'translation': 'Profesör yumruğunu ahşap masaya vurarak, "Yemek yok ve uyku da yok!" diye gürledi.', 'notes': 'slamming his fist: yumruğunu vurarak.'}, {'id': 29, 'text': 'We sat together at the large oak table, rearranging the letters in countless different combinations.', 'translation': 'Büyük meşe masada yan yana oturduk ve harfleri sayısız farklı kombinasyonda yeniden düzenledik.', 'notes': 'countless combinations: sayısız kombinasyon.'}, {'id': 30, 'text': 'The professor attempted every cryptographic method known to modern science without the slightest success.', 'translation': 'Profesör modern bilimin bildiği her kriptografik yöntemi denedi ama en ufak bir başarı dahi elde edemedi.', 'notes': 'without the slightest success: en ufak bir başarı olmaksızın.'}, {'id': 31, 'text': 'Hours passed, and the ticking of the grandfather clock in the hallway sounded louder and louder.', 'translation': 'Saatler geçti ve koridordaki büyük ayaklı saatin tiktakları giderek daha da yüksek duyulmaya başladı.', 'notes': 'grandfather clock: büyük sarkaçlı ayaklı saat.'}, {'id': 32, 'text': 'My head began to ache violently, and my empty stomach protested against this sudden forced fast.', 'translation': 'Başım şiddetle ağrımaya başladı ve boş midem bu ani zorunlu açlığa isyan etti.', 'notes': 'forced fast: zorunlu oruç / açlık.'}, {'id': 33, 'text': 'I knew very well that my uncle would rather die of starvation than abandon an intellectual puzzle.', 'translation': 'Amcamın entelektüel bir bilmeceyi bırakmaktansa açlıktan ölmeyi tercih edeceğini gayet iyi biliyordum.', 'notes': 'would rather die than abandon: vazgeçmektense ölmeyi yeğler.'}, {'id': 34, 'text': 'At midnight, exhausted and frustrated, the professor put on his hat and stormed out into the street.', 'translation': 'Gece yarısı, yorgun ve hüsrana uğramış bir halde profesör şapkasını takıp sokağa fırladı.', 'notes': 'stormed out into: hışımla dışarı fırladı.'}, {'id': 35, 'text': 'He needed cold air to cool his burning brain, leaving me alone in the dimly lit study.', 'translation': 'Yanan beynini soğutmak için soğuk havaya ihtiyacı vardı ve beni loş ışıklı çalışma odasında yalnız bıraktı.', 'notes': 'dimly lit study: loş ışıklı çalışma odası.'}, {'id': 36, 'text': 'I collapsed into his comfortable armchair, feeling utterly miserable and desperate for a crust of bread.', 'translation': 'Bir lokma ekmeğe muhtaç ve son derece perişan hissederek onun rahat koltuğuna yığıldım.', 'notes': 'collapsed into: içine yığıldı.'}, {'id': 37, 'text': 'I thought about my lovely fiancée, Graüben, who was currently staying with relatives in Altona.', 'translation': "O sırada Altona'daki akrabalarının yanında kalan sevgili nişanlım Graüben'i düşündüm.", 'notes': 'lovely fiancée: sevgili nişanlı.'}, {'id': 38, 'text': '"If my uncle stays in this terrible mood, we will never be able to get married," I sighed.', 'translation': '"Eğer amcam bu berbat ruh halinde kalırsa, asla evlenemeyeceğiz," diye iç çektim.', 'notes': 'terrible mood: berbat ruh hali.'}, {'id': 39, 'text': 'To distract myself from hunger, I picked up the mysterious parchment once again.', 'translation': 'Açlıktan dikkatimi dağıtmak için gizemli parşömeni bir kez daha elime aldım.', 'notes': 'distract myself from: dikkatimi ...den başka yöne çekmek.'}, {'id': 40, 'text': 'Little did I know that a pure accident was about to change our lives forever.', 'translation': 'Tamamen tesadüfi bir olayın hayatlarımızı sonsuza dek değiştirmek üzere olduğundan habersizdim.', 'notes': 'little did I know: neredeyse hiç bilmiyordum / haberim yoktu.'}]}, {'page_no': 3, 'title': 'Axel Deciphers the Secret Message', 'tr_title': "Yeğen Axel'ın Şifreyi Tesadüfen Çözmesi: Sneffels Yanardağı Krateri", 'vocab_focus': [('decipher', 'şifreyi çözmek'), ('crater', 'krater, volkan ağzı'), ('subterranean', 'yer altı, yerin altındaki'), ('shadow', 'gölge'), ('summit', 'zirve, doruk'), ('flabbergasted', 'şaşkına dönmüş, donakalmış'), ('audacious', 'cüretkar, gözü pek'), ('descend', 'alçalmak, aşağı inmek')], 'sentences': [{'id': 41, 'text': 'I was fanning myself with the sheet of paper because the room had become uncomfortably warm.', 'translation': 'Oda rahatsız edici derecede ısındığı için elimdeki kağıtla kendimi yelpazeliyordum.', 'notes': 'fanning myself: kendimi yelpazeliyordum.'}, {'id': 42, 'text': 'As the parchment moved through the candlelight, I happened to glance at its reverse side.', 'translation': 'Parşömen mum ışığından geçerken, tesadüfen arka yüzüne gözüm ilişti.', 'notes': 'happened to glance: tesadüfen gözü ilişti.'}, {'id': 43, 'text': 'The ink had soaked slightly through the thin skin, showing the characters backward against the light.', 'translation': 'Mürekkep ince deriden hafifçe sızmıştı ve harfleri ışığa karşı tersten gösteriyordu.', 'notes': 'soaked slightly through: deriden hafifçe diğer tarafa geçmişti.'}, {'id': 44, 'text': "My eyes caught recognizable Latin words like 'craterem' and 'terram'.", 'translation': "Gözlerim 'craterem' ve 'terram' gibi tanınabilir Latince kelimelere çarptı.", 'notes': 'caught recognizable words: tanıdık kelimeleri yakaladı.'}, {'id': 45, 'text': '"Good heavens!" I cried, leaping out of the chair with my heart pounding against my ribs.', 'translation': 'Kalbim kaburgalarıma çarparak sandalyeden fırlayıp, "Aman Tanrım!" diye haykırdım.', 'notes': 'leaping out of the chair: sandalyeden fırlayarak.'}, {'id': 46, 'text': 'The text was not written in Icelandic at all; it was written in Latin disguised with runic letters!', 'translation': 'Metin kesinlikle İzlandaca yazılmamıştı; rünik harflerle gizlenmiş Latinceydi!', 'notes': 'disguised with: ...ile gizlenmiş / kamufle edilmiş.'}, {'id': 47, 'text': 'Moreover, it had to be read backward from right to left and from the bottom up.', 'translation': 'Üstelik sağdan sola ve aşağıdan yukarıya doğru tersten okunması gerekiyordu.', 'notes': 'from the bottom up: aşağıdan yukarıya doğru.'}, {'id': 48, 'text': 'With trembling hands, I took a pen and transcribed the letters in their proper order.', 'translation': 'Titreyen ellerle bir kalem aldım ve harfleri doğru sıralarıyla kağıda döktüm.', 'notes': 'transcribed in proper order: doğru sırayla kopyaladı / yazdı.'}, {'id': 49, 'text': 'Within five minutes, the terrifying sentence formed clearly before my startled eyes.', 'translation': 'Beş dakika içinde o korkunç cümle ürkmüş gözlerimin önünde apaçık belirdi.', 'notes': 'startled eyes: ürkmüş / şaşkın gözler.'}, {'id': 50, 'text': '"Descend into the crater of Sneffels Jokull which the shadow of Scartaris touches before the kalends of July."', 'translation': '"Temmuz ayının başlangıcından önce Scartaris\'in gölgesinin dokunduğu Sneffels Jokull kraterine in."', 'notes': 'descend into the crater: kratere in.'}, {'id': 51, 'text': '"And you will reach the center of the Earth, bold traveler!"', 'translation': '"Ve böylece Dünya\'nın merkezine ulaşacaksın, cesur gezgin!"', 'notes': 'bold traveler: cesur yolcu / gezgin.'}, {'id': 52, 'text': 'The final line was signed plainly: "I did this. Arne Saknussemm."', 'translation': 'Son satır açıkça imzalanmıştı: "Bunu ben yaptım. Arne Saknussemm."', 'notes': 'signed plainly: sade bir şekilde imzalanmış.'}, {'id': 53, 'text': 'I stood frozen with fear as the full meaning of those words sank into my consciousness.', 'translation': 'O kelimelerin tam anlamı bilincime yerleşirken korkudan donakalmış bir halde durdum.', 'notes': 'sank into my consciousness: bilincime işledi / oturdu.'}, {'id': 54, 'text': 'Sneffels was an extinct volcano in Iceland, standing thousands of feet above the frozen northern sea.', 'translation': "Sneffels, İzlanda'da donmuş kuzey denizinin binlerce fit üzerinde yükselen sönmüş bir yanardağdı.", 'notes': 'extinct volcano: sönmüş yanardağ.'}, {'id': 55, 'text': 'Journeying to the center of the globe was an impossible, insane nightmare that defied all geological science.', 'translation': 'Kürenin merkezine seyahat etmek, tüm jeoloji bilimine meydan okuyan imkansız ve delice bir kabustu.', 'notes': 'defied all science: tüm bilime meydan okudu.'}, {'id': 56, 'text': '"If my uncle discovers this, he will immediately drag me into that bottomless abyss!" I thought in panic.', 'translation': 'Panik içinde, "Eğer amcam bunu öğrenirse, beni derhal o dipsiz uçuruma sürükler!" diye düşündüm.', 'notes': 'bottomless abyss: dipsiz uçurum.'}, {'id': 57, 'text': 'I walked toward the fireplace, determined to throw both the parchment and my transcription into the embers.', 'translation': 'Hem parşömeni hem de çevirimi közlerin içine atmaya kararlı bir şekilde şömineye doğru yürüdüm.', 'notes': 'into the embers: kor ateşlerin içine.'}, {'id': 58, 'text': 'Destruction of the secret was the only way to save our lives from a certain and horrific death.', 'translation': 'Sırrın yok edilmesi, hayatlarımızı kesin ve korkunç bir ölümden kurtarmanın tek yoluydu.', 'notes': 'certain and horrific death: kesin ve korkunç ölüm.'}, {'id': 59, 'text': 'Just as my hand reached toward the fire, the heavy street door opened with a loud creak.', 'translation': 'Tam elim ateşe doğru uzanırken, ağır sokak kapısı yüksek bir gıcırtıyla açıldı.', 'notes': 'with a loud creak: yüksek bir gıcırtıyla.'}, {'id': 60, 'text': 'Professor Otto Lidenbrock had returned from his walk, his heavy footsteps echoing up the stairs.', 'translation': 'Profesör Otto Lidenbrock yürüyüşünden dönmüştü ve ağır ayak sesleri merdivenlerde yankılanıyordu.', 'notes': 'footsteps echoing: yankılanan ayak sesleri.'}]}, {'page_no': 4, 'title': "Lidenbrock's Enthusiasm and Axel's Doubts", 'tr_title': "Lidenbrock'un Büyük Heyecanı ve Axel'ın Endişeleri", 'vocab_focus': [('inevitable', 'kaçınılmaz'), ('subterranean', 'yeraltına ait'), ('temperature', 'sıcaklık, ısı'), ('enthusiastic', 'hevesli, coşkulu'), ('molten', 'erimiş (kaya, lav)'), ('contradict', 'çelişmek, aksini iddia etmek'), ('preparation', 'hazırlık'), ('destiny', 'kader, yazgı')], 'sentences': [{'id': 61, 'text': 'I had barely enough time to throw the papers back onto the desk before my uncle burst into the room.', 'translation': 'Amcam odaya dalmadan önce kağıtları masanın üzerine geri fırlatacak kadar ancak vakit bulabilmiştim.', 'notes': 'barely enough time: ancak yetecek kadar zaman.'}, {'id': 62, 'text': 'He looked weary and dejected, having failed to find inspiration during his wandering through the streets.', 'translation': 'Sokaklarda dolaşırken aradığı ilhamı bulamamış, yorgun ve kederli görünüyordu.', 'notes': 'weary and dejected: yorgun ve kederli / çökkün.'}, {'id': 63, 'text': 'I tried to hide my trembling, but my conscience could not bear seeing him suffer from hunger and grief.', 'translation': 'Titrememi gizlemeye çalıştım ama vicdanım onun açlık ve keder içinde kıvranmasına dayanamadı.', 'notes': 'could not bear seeing: görmeye dayanamadı.'}, {'id': 64, 'text': '"Uncle," I said softly, unable to keep the tremendous truth to myself any longer, "I have read the message."', 'translation': 'Muazzam gerçeği daha fazla kendime saklayamayarak usulca, "Amca," dedim, "mesajı okudum."', 'notes': 'keep to myself: kendime saklamak.'}, {'id': 65, 'text': 'The professor froze in his tracks, staring at me as if I had lost my mind.', 'translation': 'Profesör olduğu yerde donakaldı, aklımı kaçırmışım gibi bana dik dik baktı.', 'notes': 'froze in his tracks: olduğu yerde donakaldı.'}, {'id': 66, 'text': 'When I placed the decoded Latin translation in his hands, his face turned pale with overwhelming emotion.', 'translation': 'Çözümlenmiş Latince çeviriyi ellerine bıraktığımda, yüzü ezici bir duygu seliyle soldu.', 'notes': 'overwhelming emotion: ezici / yoğun duygu.'}, {'id': 67, 'text': 'He read the words three times in complete silence, breathing heavily like a runner nearing the finish line.', 'translation': 'Bitiş çizgisine yaklaşan bir koşucu gibi ağır ağır soluyarak sözleri tam bir sessizlik içinde üç kez okudu.', 'notes': 'breathing heavily: derin ve ağır soluyarak.'}, {'id': 68, 'text': '"Arne Saknussemm actually accomplished it!" he roared, leaping into the air with childlike joy.', 'translation': 'Çocuksu bir sevinçle havaya zıplayarak, "Arne Saknussemm bunu gerçekten başarmış!" diye kükredi.', 'notes': 'leaping into the air: havaya zıplayarak.'}, {'id': 69, 'text': '"Axel, my boy, we are going to follow his footsteps into the bowels of the planet!"', 'translation': '"Axel, oğlum, onun ayak izlerini gezegenin bağrına kadar takip edeceğiz!"', 'notes': 'into the bowels of: ...nın bağrına / derinliklerine.'}, {'id': 70, 'text': 'I tried desperately to present scientific objections to this mad undertaking.', 'translation': 'Bu çılgınca girişime bilimsel itirazlar sunmak için çaresizce çabaladım.', 'notes': 'mad undertaking: çılgın girişim.'}, {'id': 71, 'text': '"Uncle, modern geologists believe that the interior of the Earth is a mass of incandescent, molten rock!"', 'translation': '"Amca, modern jeologlar Dünya\'nın içinin akkor halinde, erimiş kaya kütlesi olduğuna inanıyor!"', 'notes': 'incandescent molten rock: akkor erimiş kaya.'}, {'id': 72, 'text': '"The heat at fifty miles beneath the surface would melt steel and vaporize human flesh in seconds!"', 'translation': '"Yüzeyin elli mil altındaki ısı, çeliği eritir ve insan etini saniyeler içinde buharlaştırır!"', 'notes': 'vaporize human flesh: insan etini buharlaştırmak.'}, {'id': 73, 'text': 'The professor waved his hand dismissively, scoffing at conventional theories.', 'translation': 'Profesör alışılagelmiş teorilerle alay ederek elini umursamazca salladı.', 'notes': 'scoffing at: ...ile alay ederek / küçümseyerek.'}, {'id': 74, 'text': '"Theories are merely guesses invented by armchair scholars who never venture into the field!" he replied.', 'translation': '"Teoriler, asla sahaya çıkmayan masa başı bilginlerin uydurduğu tahminlerden ibarettir!" diye yanıtladı.', 'notes': 'armchair scholars: masa başı bilginler.'}, {'id': 75, 'text': '"Saknussemm went there and returned alive to write this testament, and that is empirical proof enough for me."', 'translation': '"Saknussemm oraya bizzat gitti ve bu vasiyeti yazmak için sağ döndü; bu da benim için yeterli deneysel kanıttır."', 'notes': 'empirical proof: deneysel kanıt.'}, {'id': 76, 'text': 'He declared that our journey would begin without delay, before the shadow of Scartaris touched Sneffels in late June.', 'translation': "Scartaris'in gölgesi haziran sonunda Sneffels'e dokunmadan önce yolculuğumuzun gecikmeksizin başlayacağını ilan etti.", 'notes': 'without delay: gecikmeksizin.'}, {'id': 77, 'text': 'Martha was ordered to unlock the pantry and prepare provisions for an extended expedition.', 'translation': "Martha'ya kileri açması ve uzun sürecek bir keşif gezisi için erzak hazırlaması emredildi.", 'notes': 'extended expedition: kapsamlı / uzun keşif gezisi.'}, {'id': 78, 'text': 'I wandered through the house in a daze, packing scientific instruments, barometers, and sturdy clothing.', 'translation': 'Bilimsel aletleri, barometreleri ve dayanıklı giysileri valizlere doldururken evin içinde sersemlemiş bir halde gezindim.', 'notes': 'in a daze: sersemlemiş / şaşkın halde.'}, {'id': 79, 'text': 'Graüben, to my immense surprise, encouraged me when I confessed my fears to her later that evening.', 'translation': 'O akşam korkularımı itiraf ettiğimde, Graüben beni çok şaşırtarak gitmem yönünde yüreklendirdi.', 'notes': 'encouraged me: beni yüreklendirdi / cesaretlendirdi.'}, {'id': 80, 'text': '"Go, Axel!" she whispered with shining eyes. "A glorious reputation awaits you, and I will be proud to become your wife upon your return."', 'translation': 'Işıldayan gözleriyle, "Git Axel!" diye fısıldadı. "Seni şanlı bir itibar bekliyor ve döndüğünde karın olmaktan gurur duyacağım."', 'notes': 'glorious reputation: şanlı bir şöhret / itibar.'}]}, {'page_no': 5, 'title': 'From Hamburg to Reykjavik Across Stormy Seas', 'tr_title': "Hamburg'dan Kopenhag'a ve Oradan Reykjavik'e Deniz Yolculuğu", 'vocab_focus': [('expedition', 'keşif yolculuğu'), ('schooner', 'uskuna, yelkenli gemi'), ('navigation', 'seyrüsefer, gemi yolculuğu'), ('seasickness', 'deniz tutması'), ('horizon', 'ufuk çizgisi'), ('glacier', 'buzul'), ('inhospitable', 'misafirperver olmayan, çorak, sert'), ('harbor', 'liman')], 'sentences': [{'id': 81, 'text': 'On the second of June, our luggage was loaded aboard the steamer departing for Copenhagen.', 'translation': "2 Haziran'da eşyalarımız Kopenhag'a hareket eden buharlı gemiye yüklendi.", 'notes': 'loaded aboard the steamer: buharlı gemiye yüklendi.'}, {'id': 82, 'text': 'My uncle was in highest spirits, checking every thermometer, chronometer, and Ruhmkorff electric coil.', 'translation': 'Her termometreyi, kronometreyi ve Ruhmkorff elektrik bobinini kontrol eden amcamın neşesi son derece yerindeydi.', 'notes': 'in highest spirits: keyfi en üst seviyede.'}, {'id': 83, 'text': 'These special Ruhmkorff lamps would provide safe, portable illumination in underground caverns without risk of gas explosions.', 'translation': 'Bu özel Ruhmkorff lambaları, gaz patlaması riski olmadan yeraltı mağaralarında güvenli ve taşınabilir aydınlatma sağlayacaktı.', 'notes': 'portable illumination: taşınabilir aydınlatma.'}, {'id': 84, 'text': 'We arrived in Denmark after a smooth passage and consulted the renowned Danish scholar, Dr. Thomson.', 'translation': "Sorunsuz bir geçişin ardından Danimarka'ya ulaştık ve ünlü Danimarkalı bilim insanı Dr. Thomson'a danıştık.", 'notes': 'renowned Danish scholar: tanınmış Danimarkalı bilgin.'}, {'id': 85, 'text': 'Dr. Thomson provided us with warm letters of introduction to the Governor of Iceland and other notable authorities.', 'translation': "Dr. Thomson, İzlanda Valisi'ne ve diğer önde gelen yetkililere hitaben bize samimi tavsiye mektupları verdi.", 'notes': 'letters of introduction: tavsiye / tanıtım mektupları.'}, {'id': 86, 'text': 'On the seventh of June, we boarded the Valkyrie, a double-masted schooner carrying mail and cargo to Reykjavik.', 'translation': "7 Haziran'da Reykjavik'e posta ve yük taşıyan çift direkli bir uskuna olan Valkyrie'ye bindik.", 'notes': 'double-masted schooner: çift direkli uskuna.'}, {'id': 87, 'text': 'As soon as the ship reached the open North Sea, a ferocious storm battered our wooden hull.', 'translation': "Gemi açık Kuzey Denizi'ne çıkar çıkmaz azgın bir fırtına ahşap teknemizi dövmeye başladı.", 'notes': 'ferocious storm battered: azgın fırtına dövdü / hırpaladı.'}, {'id': 88, 'text': 'I spent five miserable days groaning in my narrow bunk, utterly incapacitated by violent seasickness.', 'translation': 'Şiddetli deniz tutması yüzünden tamamen takatten düşmüş halde, dar ranzamda inleyerek beş perişan gün geçirdim.', 'notes': 'utterly incapacitated: tamamen hareket edemez / güçsüz düşmüş.'}, {'id': 89, 'text': 'My uncle, on the contrary, seemed completely immune to the tossing waves and ate heavy meals on the deck.', 'translation': 'Amcam ise tam tersine, çalkalanan dalgalara karşı tamamen bağışık görünüyordu ve güvertede ağır yemekler yiyordu.', 'notes': 'immune to tossing waves: çalkantılı dalgalara bağışık.'}, {'id': 90, 'text': 'He chatted with the captain and calculated our geographical coordinates with unwavering precision.', 'translation': 'Kaptanla sohbet etti ve coğrafi koordinatlarımızı sarsılmaz bir hassasiyetle hesapladı.', 'notes': 'unwavering precision: sarsılmaz hassasiyet.'}, {'id': 91, 'text': 'By the tenth day of our voyage, the wild wind subsided and the gray mist began to lift.', 'translation': 'Yolculuğumuzun onuncu gününde vahşi rüzgar dindi ve gri sis dağılmaya başladı.', 'notes': 'wind subsided: rüzgar dindi / yatıştı.'}, {'id': 92, 'text': 'Far on the northern horizon, a jagged land of dark basalt rock and glittering glaciers appeared.', 'translation': 'Kuzey ufkunda uzakta, koyu renk bazalt kayalarından ve parıldayan buzullardan oluşan sarp bir kara belirdi.', 'notes': 'jagged land: girintili çıkıntılı / sarp kara parçası.'}, {'id': 93, 'text': '"Iceland!" the lookout shouted from the top of the main mast.', 'translation': 'Gözcü ana direğin tepesinden, "İzlanda!" diye bağırdı.', 'notes': 'lookout shouted: gözcü bağırdı.'}, {'id': 94, 'text': 'The Valkyrie sailed smoothly into the calm bay of Faxaflói, surrounded by volcanic mountains.', 'translation': "Valkyrie, volkanik dağlarla çevrili Faxaflói'nin sakin koyuna usulca süzüldü.", 'notes': 'calm bay: sakin koy / körfez.'}, {'id': 95, 'text': 'Reykjavik presented itself as a modest town consisting of two rows of simple wooden cottages painted red.', 'translation': 'Reykjavik, kırmızıya boyanmış iki sıra sade ahşap kulübeden oluşan mütevazı bir kasaba görünümündeydi.', 'notes': 'modest town: mütevazı kasaba.'}, {'id': 96, 'text': 'The surrounding landscape was desolate, bare of trees, and marked everywhere by ancient lava flows.', 'translation': 'Çevredeki arazi ıssızdı, ağaçtan yoksundu ve her yeri kadim lav akıntılarıyla damgalanmıştı.', 'notes': 'bare of trees: ağaçtan yoksun.'}, {'id': 97, 'text': 'Yet in the crisp northern air, one majestic peak dominated the entire western horizon.', 'translation': 'Yine de o berrak kuzey havasında, görkemli bir zirve batı ufkunun tamamına hükmediyordu.', 'notes': 'dominated the horizon: ufka hükmediyordu.'}, {'id': 98, 'text': 'It was Sneffels Jokull, wearing a glistening crown of perpetual snow like an ancient white giant.', 'translation': "Kadim beyaz bir dev gibi parıldayan ebedi kar tacını takmış olan Sneffels Jokull'du bu.", 'notes': 'perpetual snow: ebedi / erimeyen kar.'}, {'id': 99, 'text': 'Professor Lidenbrock pointed his finger toward the gleaming summit and squeezed my shoulder tightly.', 'translation': 'Profesör Lidenbrock parmağıyla ışıldayan zirveyi işaret etti ve omzumu sıkıca sıktı.', 'notes': 'squeezed my shoulder: omzumu sıktı.'}, {'id': 100, 'text': '"There is our gateway, Axel," he murmured gravely. "The entrance to the center of the world."', 'translation': '"İşte bizim kapımız orada, Axel," diye ciddiyetle mırıldandı. "Dünyanın merkezine açılan giriş kapısı."', 'notes': 'murmured gravely: ciddiyetle mırıldandı.'}]}, {'page_no': 6, 'title': 'Meeting Hans Bjelke the Guide', 'tr_title': 'Soğukkanlı ve Sadık İzlandalı Rehber Hans Bjelke ile Tanışma', 'vocab_focus': [('phlegmatic', 'soğukkanlı, sakin, duygularını belli etmeyen'), ('guide', 'rehber'), ('eiderdown', 'kuş tüyü (eider ördeği tüyü)'), ('reliable', 'güvenilir, itimat edilir'), ('contract', 'sözleşme, anlaşma'), ('taciturn', 'az konuşan, suskun'), ('devotion', 'bağlılık, sadakat'), ('invaluable', 'paha biçilmez, çok kıymetli')], 'sentences': [{'id': 101, 'text': 'In Reykjavik, the local Governor welcomed us with genuine warmth and arranged lodgings at the town school.', 'translation': "Reykjavik'te yerel vali bizi samimi bir sıcaklıkla karşıladı ve kasaba okulunda konaklama ayarladı.", 'notes': 'genuine warmth: samimi bir sıcaklık.'}, {'id': 102, 'text': 'The local mayor introduced us to a native hunter named Hans Bjelke, who was recommended as the perfect guide.', 'translation': 'Yerel belediye başkanı, mükemmel bir rehber olarak tavsiye edilen Hans Bjelke adında yerli bir avcıyla bizi tanıştırdı.', 'notes': 'native hunter: yerli avcı.'}, {'id': 103, 'text': 'Hans was tall, muscular, and exceptionally calm, with long blond hair falling over his broad shoulders.', 'translation': 'Hans uzun boylu, kaslı ve son derece sakindi; uzun sarı saçları geniş omuzlarına dökülüyordu.', 'notes': 'exceptionally calm: olağanüstü derecede sakin.'}, {'id': 104, 'text': 'His blue eyes reflected the quiet stillness of the arctic wilderness, showing neither fear nor excessive curiosity.', 'translation': 'Mavi gözleri, ne korku ne de aşırı bir merak sergileyerek kutup yaban hayatının sessiz dinginliğini yansıtıyordu.', 'notes': 'quiet stillness: sessiz dinginlik.'}, {'id': 105, 'text': 'He made his living by collecting eiderdown from the sea ducks that nested upon the rocky cliffs.', 'translation': 'Geçimini kayalık uçurumlarda yuva yapan deniz ördeklerinden eider kuştüyü toplayarak sağlıyordu.', 'notes': 'made his living by: ...ile geçimini sağlıyordu.'}, {'id': 106, 'text': "My uncle was immediately impressed by the man's extraordinary composure and physical strength.", 'translation': 'Amcam, adamın olağanüstü soğukkanlılığından ve fiziksel kuvvetinden hemen etkilendi.', 'notes': 'extraordinary composure: olağanüstü soğukkanlılık.'}, {'id': 107, 'text': 'Hans spoke very little, using only a few words of Danish to answer our questions directly.', 'translation': 'Hans çok az konuşuyor, sorularımıza doğrudan cevap vermek için yalnızca birkaç Danimarkaca kelime kullanıyordu.', 'notes': 'spoke very little: çok az konuşurdu.'}, {'id': 108, 'text': 'When my uncle offered him three rix-dollars a week, Hans simply nodded his head in silent agreement.', 'translation': 'Amcam ona haftalık üç rix-dolar teklif ettiğinde, Hans sessiz bir mutabakatla sadece başını salladı.', 'notes': 'silent agreement: sessiz mutabakat.'}, {'id': 109, 'text': '"He is a phlegmatic marvel," my uncle declared with profound satisfaction.', 'translation': 'Amcam derin bir memnuniyetle, "O, soğukkanlılık abidesi bir harika," diye belirtti.', 'notes': 'phlegmatic marvel: soğukkanlı bir harika.'}, {'id': 110, 'text': '"He will obey orders without asking foolish questions or arguing about the destination."', 'translation': '"Aptalca sorular sormadan ya da gidilecek yer hakkında tartışmadan emirlere itaat edecektir."', 'notes': 'obey orders: emirlere itaat etmek.'}, {'id': 111, 'text': 'Hans arranged four sturdy Icelandic ponies to carry our heavy instruments, firearms, and baggage.', 'translation': 'Hans ağır aletlerimizi, ateşli silahlarımızı ve bagajlarımızı taşımak için dört dayanıklı İzlanda midillisi ayarladı.', 'notes': 'sturdy Icelandic ponies: dayanıklı İzlanda midillileri.'}, {'id': 112, 'text': 'These small northern horses were sure-footed and capable of traversing the most treacherous volcanic terrains.', 'translation': 'Bu küçük kuzey atları yere sağlam basıyordu ve en tehlikeli volkanik arazileri aşma yeteneğine sahipti.', 'notes': 'sure-footed: yere sağlam basan.'}, {'id': 113, 'text': 'We packed leather flasks filled with fresh spring water and concentrated meat extracts for our nourishment.', 'translation': 'Beslenmemiz için taze kaynak suyuyla dolu deri mataralar ve konsantre et özleri paketledik.', 'notes': 'leather flasks: deri mataralar.'}, {'id': 114, 'text': "On the morning of the fifteenth of June, our little caravan stood ready outside the mayor's residence.", 'translation': '15 Haziran sabahında küçük kervanımız belediye başkanının konutunun önünde hazır bekliyordu.', 'notes': 'little caravan: küçük kervan.'}, {'id': 115, 'text': 'The inhabitants of Reykjavik came out into the street to wave us farewell, thinking we were merely visiting geysers.', 'translation': 'Reykjavik sakinleri, yalnızca gayzerleri ziyaret ettiğimizi düşünerek bize veda etmek için sokağa döküldü.', 'notes': 'wave us farewell: bize el sallayarak veda etmek.'}, {'id': 116, 'text': 'None of them suspected that our true goal lay miles below the volcanic crust of their island.', 'translation': 'Hiçbiri gerçek hedefimizin adalarının volkanik kabuğunun miller boyu altında yattığından şüphelenmiyordu.', 'notes': 'volcanic crust: volkanik yer kabuğu.'}, {'id': 117, 'text': 'Hans rode ahead at a steady, rhythmic pace, leading the pack animals with unmatched skill.', 'translation': 'Hans, yük hayvanlarını eşsiz bir ustalıkla yöneterek düzenli ve ritmik bir tempoda önden sürdü.', 'notes': 'steady rhythmic pace: düzenli ritmik tempo.'}, {'id': 118, 'text': 'My uncle rode behind him, his eyes glued firmly to the distant cone of Mount Sneffels.', 'translation': "Amcam, gözlerini uzaktaki Sneffels Dağı'nın konisine sımsıkı dikmiş bir halde onun ardından biniyordu.", 'notes': 'eyes glued firmly: gözleri sımsıkı kilitlenmiş.'}, {'id': 119, 'text': 'I brought up the rear, feeling a heavy dread knotting in the pit of my stomach.', 'translation': 'Karnımın tam ortasında ağır bir dehşet düğümlenerek en arkadan geliyordum.', 'notes': 'brought up the rear: en arkadan gelmek.'}, {'id': 120, 'text': 'Every step our horses took was carrying us closer to the unknown abyss.', 'translation': 'Atlarımızın attığı her adım bizi bilinmeyen uçuruma daha da yaklaştırıyordu.', 'notes': 'carrying us closer: bizi daha da yaklaştırıyordu.'}]}, {'page_no': 7, 'title': 'Ascending the Volcanic Summit of Sneffels', 'tr_title': 'Sneffels Kraterine Tırmanış ve Sönmüş Yanardağın Ağzı', 'vocab_focus': [('ascent', 'tırmanış, yukarı çıkış'), ('slope', 'yamaç, meyil'), ('exhaustion', 'aşırı bitkinlik, tükenme'), ('crevasse', 'buzul yarığı, çatlak'), ('crater', 'krater'), ('precipice', 'uçurum, sarp kayalık'), ('dizziness', 'baş dönmesi'), ('majestic', 'görkemli, haşmetli')], 'sentences': [{'id': 121, 'text': 'For several days we traveled across bleak plains formed of solidified black basalt and porous pumice stone.', 'translation': 'Günlerce katılaşmış siyah bazalt ve gözenekli ponza taşından oluşmuş kasvetli ovaları aştık.', 'notes': 'solidified black basalt: katılaşmış siyah bazalt.'}, {'id': 122, 'text': 'The ground was cracked by ancient earthquakes, creating deep fissures that forced our caravan to make long detours.', 'translation': 'Zemin, kervanımızı uzun dönemeçler yapmaya zorlayan derin yarıklar oluşturan kadim depremlerle çatlamıştı.', 'notes': 'make long detours: uzun dönemeçler / sapmalar yapmak.'}, {'id': 123, 'text': 'On the twenty-third of June, we arrived at the tiny seaside hamlet of Stapi at the foot of Sneffels.', 'translation': "23 Haziran'da Sneffels'in eteğindeki küçük deniz kenarı köyü Stapi'ye vardık.", 'notes': 'at the foot of: ...nın eteğinde.'}, {'id': 124, 'text': 'Here the steep slopes began, rising abruptly from the freezing waves of the Atlantic Ocean.', 'translation': "Burada dik yamaçlar başlıyor, Atlantik Okyanusu'nun dondurucu dalgalarından aniden yükseliyordu.", 'notes': 'rising abruptly: aniden yükselen.'}, {'id': 125, 'text': 'We were forced to leave our faithful ponies behind, as no quadruped could climb such precipitous rocks.', 'translation': 'Sadık midillilerimizi geride bırakmak zorunda kaldık, zira hiçbir dört ayaklı böylesine sarp kayalara tırmanamazdı.', 'notes': 'leave behind: geride bırakmak.'}, {'id': 126, 'text': 'Hans divided the essential baggage into three heavy bundles, strapping the largest load onto his own shoulders.', 'translation': 'Hans temel eşyaları üç ağır çıkına böldü ve en büyük yükü kendi omuzlarına bağladı.', 'notes': 'strapping onto shoulders: omuzlarına bağlayarak.'}, {'id': 127, 'text': 'At five in the morning on the twenty-fourth, our difficult pedestrian ascent commenced.', 'translation': 'Ayın yirmi dördü sabah saat beşte, zorlu yaya tırmanışımız başladı.', 'notes': 'pedestrian ascent: yaya tırmanışı.'}, {'id': 128, 'text': 'We advanced along sharp ridges of volcanic slag, slipping frequently on the loose stones.', 'translation': 'Gevşek taşların üzerinde sık sık kayarak volkanik cürufun keskin sırtları boyunca ilerledik.', 'notes': 'volcanic slag: volkanik cüruf / taş artığı.'}, {'id': 129, 'text': 'Hans cut steps in the icy crust with his axe whenever we encountered dangerous frozen snowfields.', 'translation': 'Hans, ne zaman tehlikeli donmuş kar yığınlarıyla karşılaşsak baltasıyla buzlu kabuğa basamaklar oydu.', 'notes': 'cut steps with axe: baltayla basamaklar açtı.'}, {'id': 130, 'text': 'The thin mountain air made breathing labored and painful, sending sharp stabs through my burning chest.', 'translation': 'Dağın seyrelmiş havası nefes almayı zahmetli ve acı verici hale getirdi, yanan göğsüme keskin batmalar sapladı.', 'notes': 'breathing labored: soluk alıp vermeyi güçleştirdi.'}, {'id': 131, 'text': 'My uncle climbed with surprising agility, driven forward by his fanatical scientific ambition.', 'translation': 'Amcam, bağnaz bilimsel hırsının verdiği güçle şaşırtıcı bir çeviklikle tırmanıyordu.', 'notes': 'fanatical ambition: bağnaz / fanatik hırs.'}, {'id': 132, 'text': 'Whenever I stopped to rest, he grabbed my arm and urged me upward without mercy.', 'translation': 'Dinlenmek için her durduğumda kolumu yakalıyor ve beni acımasızca yukarıya doğru zorluyordu.', 'notes': 'urged me upward: beni yukarıya doğru zorladı.'}, {'id': 133, 'text': 'By midday, a thick veil of clouds surrounded us, obscuring both the summit above and the valleys below.', 'translation': 'Öğle vaktine doğru kalın bir bulut örtüsü etrafımızı sardı; hem yukarıdaki zirveyi hem de aşağıdaki vadileri örttü.', 'notes': 'thick veil of clouds: kalın bulut örtüsü.'}, {'id': 134, 'text': 'We walked along the brink of terrifying precipices where a single misstep meant plunging thousands of feet to our doom.', 'translation': 'Tek bir hatalı adımın binlerce fit aşağıya, ölüme yuvarlanmak anlamına geldiği korkunç uçurumların kenarında yürüdük.', 'notes': 'brink of precipices: uçurumların eşiği / kenarı.'}, {'id': 135, 'text': 'A sudden gust of wind scattered the fog at last, revealing the twin peaks of Mount Sneffels towering over us.', 'translation': "Aniden esen bir rüzgar dalgası sonunda sisi dağıttı ve Sneffels Dağı'nın tepemizde yükselen ikiz zirvelerini açığa çıkardı.", 'notes': 'scattered the fog: sisi dağıttı.'}, {'id': 136, 'text': "One of these soaring cones was named Scartaris, the very landmark mentioned in Saknussemm's coded cipher.", 'translation': "Bu yükselen konilerden biri, Saknussemm'in şifreli metninde adı geçen o meşhur nirengi noktası Scartaris'ti.", 'notes': 'the very landmark: tam da o nirengi noktası.'}, {'id': 137, 'text': "At eleven o'clock that night, under the pale glow of the midnight sun, we reached the circular rim.", 'translation': 'O gece saat on birde, gece yarısı güneşinin soluk ışıltısı altında dairesel krater kenarına ulaştık.', 'notes': 'circular rim: dairesel kenar / çember.'}, {'id': 138, 'text': 'Before us opened the immense crater of the volcano, an inverted cone a mile wide and five thousand feet deep.', 'translation': 'Önümüzde bir mil genişliğinde ve beş bin fit derinliğinde ters bir huni olan devasa yanardağ krateri açılıyordu.', 'notes': 'inverted cone: ters koni / huni.'}, {'id': 139, 'text': 'Its gloomy bottom was silent and motionless, showing no smoke or sign of volcanic activity for over six centuries.', 'translation': 'Kasvetli dibi sessiz ve hareketsizdi; altı yüzyılı aşkın süredir hiçbir duman veya volkanik faaliyet emaresi sergilemiyordu.', 'notes': 'gloomy bottom: kasvetli taban.'}, {'id': 140, 'text': '"We are at the threshold!" Professor Lidenbrock exclaimed triumphantly, his voice echoing into the dark chasm.', 'translation': 'Profesör Lidenbrock, sesi karanlık yarığın içinde yankılanarak zafer dolu bir haykırışla, "Eşikteyiz!" dedi.', 'notes': 'at the threshold: eşikte / kapının önünde.'}]}, {'page_no': 8, 'title': 'The Shadow of Scartaris Points the Way', 'tr_title': 'Temmuz Güneşinin Gölgesi: Doğru Krater Bacasına İniş', 'vocab_focus': [('chimney', 'baca, volkanik kanal'), ('shadow', 'gölge'), ('meridian', 'meridyen, öğle vakti dairesi'), ('solstice', 'gündönümü'), ('shaft', 'kuyu, dikey galeri'), ('inscribed', 'kazınmış, hakkedilmiş'), ('fateful', 'kader belirleyici, tarihi'), ('unmistakable', 'kesin, şüphe götürmez')], 'sentences': [{'id': 141, 'text': 'We camped for the night inside the sheltering hollow of the crater rim, wrapped in thick woolen blankets.', 'translation': 'Kalın yün battaniyelere sarınmış halde, krater kenarının korunaklı çukurunda geceyi geçirmek üzere kamp kurduk.', 'notes': 'sheltering hollow: korunaklı çukur.'}, {'id': 142, 'text': 'At midnight in late June at this high latitude, the sun barely touched the ocean horizon before rising again.', 'translation': 'Bu yüksek enlemde haziran sonu gece yarısında güneş, tekrar yükselmeden önce okyanus ufkuna ancak değiyordu.', 'notes': 'barely touched the horizon: ufka ancak değiyordu.'}, {'id': 143, 'text': 'The next morning, the twenty-fifth of June, dawned bright, cloudless, and exceptionally clear.', 'translation': 'Ertesi sabah, 25 Haziran, pırıl pırıl, bulutsuz ve olağanüstü derecede berrak bir şekilde söktü.', 'notes': 'dawned bright: pırıl pırıl aydınlandı.'}, {'id': 144, 'text': 'We scrambled carefully down the sloping interior walls to reach the bottom floor of the crater.', 'translation': 'Kraterin tabanına ulaşmak için eğimli iç duvarlardan aşağıya dikkatle tırmandık.', 'notes': 'scrambled carefully down: dikkatlice aşağıya indi / tırmandı.'}, {'id': 145, 'text': 'There we discovered three separate volcanic shafts plunging straight down into the black heart of the earth.', 'translation': 'Orada, dünyanın kara bağrına doğru dimdik inen üç ayrı volkanik kuyu keşfettik.', 'notes': 'volcanic shafts: volkanik bacalar / kuyular.'}, {'id': 146, 'text': 'Each chimney was approximately one hundred feet in diameter and opened into utter darkness.', 'translation': 'Her bir baca yaklaşık yüz fit çapındaydı ve zifiri karanlığa açılıyordu.', 'notes': 'utter darkness: zifiri karanlık.'}, {'id': 147, 'text': '"Which of these three conduits did Saknussemm follow?" I asked, hoping the mystery would prove insolvable.', 'translation': 'Gizemin çözülemez çıkacağını umarak, "Saknussemm bu üç kanaldan hangisini takip etti?" diye sordum.', 'notes': 'three conduits: üç kanal / geçit.'}, {'id': 148, 'text': '"Remember the cipher, Axel!" my uncle replied with suppressed excitement.', 'translation': 'Amcam bastırılmış bir heyecanla, "Şifreyi hatırla, Axel!" diye yanıtladı.', 'notes': 'suppressed excitement: bastırılmış heyecan.'}, {'id': 149, 'text': '"The shadow of Scartaris will caress the correct opening before the kalends of July!"', 'translation': '"Temmuz\'un ilk günlerinden önce Scartaris\'in gölgesi doğru bacayı okşayacaktır!"', 'notes': 'caress the correct opening: doğru ağzı okşayacaktır.'}, {'id': 150, 'text': 'However, on the twenty-sixth and twenty-seventh, thick storm clouds concealed the sun completely.', 'translation': 'Ne var ki ayın yirmi altısında ve yirmi yedisinde kalın fırtına bulutları güneşi tamamen gizledi.', 'notes': 'concealed the sun: güneşi gizledi.'}, {'id': 151, 'text': 'My uncle paced like a caged tiger across the volcanic floor, cursing the weather with bitter fury.', 'translation': 'Amcam kafesteki bir kaplan gibi volkanik tabanda volta attı, acı bir öfkeyle hava durumuna lanetler yağdırdı.', 'notes': 'caged tiger: kafesteki kaplan.'}, {'id': 152, 'text': 'If the sun remained hidden until July, the precise shadow would pass and our journey would be postponed for a whole year.', 'translation': 'Eğer güneş temmuza kadar saklı kalsaydı, o kesin gölge geçecek ve yolculuğumuz koca bir yıl ertelenecekti.', 'notes': 'postponed for a whole year: koca bir yıl ertelendi.'}, {'id': 153, 'text': 'Finally, on the fateful morning of the twenty-eighth of June, the sky cleared into brilliant azure.', 'translation': 'Sonunda, o tarihi 28 Haziran sabahında gökyüzü pırıl pırıl masmavi bir renge büründü.', 'notes': 'brilliant azure: pırıl pırıl masmavi.'}, {'id': 154, 'text': 'At precisely twenty minutes to twelve, the sun climbed high above the icy horn of Scartaris.', 'translation': "Tam saat on ikiye yirmi kala güneş, Scartaris'in buzlu boynuzunun yukarısına tırmandı.", 'notes': 'icy horn: buzlu boynuz / sivri uç.'}, {'id': 155, 'text': 'A long, sharp triangular shadow formed upon the crater floor, creeping slowly across the black stones.', 'translation': 'Krater tabanında uzun, keskin üçgen bir gölge oluştu ve siyah taşların üzerinde yavaşça süründü.', 'notes': 'triangular shadow: üçgen gölge.'}, {'id': 156, 'text': 'At exact solar noon, the tip of the dark shadow fell directly across the mouth of the central shaft.', 'translation': 'Tam öğle vaktinde, karanlık gölgenin ucu doğrudan merkezdeki bacanın ağzının üzerine düştü.', 'notes': 'exact solar noon: tam güneş öğlesi.'}, {'id': 157, 'text': '"Behold!" shouted the professor, raising both hands toward the heavens in triumphant ecstasy.', 'translation': 'Profesör zafer dolu bir kendinden geçişle iki elini göklere kaldırarak, "İşte bakın!" diye haykırdı.', 'notes': 'triumphant ecstasy: zafer dolu vecid / esriklik.'}, {'id': 158, 'text': 'As we rushed to the edge of the chosen abyss, Hans suddenly pointed to a rock beside the rim.', 'translation': 'Biz seçilen uçurumun kenarına koştuğumuzda, Hans birdenbire kenardaki bir kayayı işaret etti.', 'notes': 'chosen abyss: seçilmiş uçurum.'}, {'id': 159, 'text': "Carved deeply into the dark stone were two weathered runic letters: 'A. S.'", 'translation': "Koyu renk taşın içine derinlemesine oyulmuş iki aşınmış rün harfi vardı: 'A. S.'", 'notes': 'carved deeply: derince kazınmış.'}, {'id': 160, 'text': '"Arne Saknussemm!" cried my uncle. "All doubts are swept away! Forward, gentlemen, into the center of the Earth!"', 'translation': 'Amcam, "Arne Saknussemm!" diye bağırdı. "Tüm şüpheler yok oldu! İleri baylar, Dünya\'nın merkezine doğru!"', 'notes': 'swept away: süpürülüp yok edildi.'}]}, {'page_no': 9, 'title': 'Descent into the Volcanic Chimney and Lava Tunnels', 'tr_title': 'Yerin Derinliklerine Urganlarla İniş ve Lav Tünelleri', 'vocab_focus': [('conduit', 'kanal, boru hattı, geçit'), ('abyss', 'derin uçurum, yarık'), ('perpendicular', 'dik, dikey'), ('gallery', 'yer altı galerisi, tünel'), ('strata', 'jeolojik katmanlar'), ('crystallized', 'kristalleşmiş'), ('rope', 'urgan, halat'), ('vertigo', 'baş dönmesi, vertigo')], 'sentences': [{'id': 161, 'text': "The real descent into the bowels of the planet began promptly at one o'clock in the afternoon.", 'translation': 'Gezegenin bağrına asıl iniş, öğleden sonra tam saat birde başladı.', 'notes': 'bowels of the planet: gezegenin bağrı / derinlikleri.'}, {'id': 162, 'text': 'Hans uncoiled our longest ropes and secured one end firmly around a solid spur of basalt.', 'translation': 'Hans en uzun urganlarımızı açtı ve bir ucunu sağlam bir bazalt çıkıntısına sıkıca bağladı.', 'notes': 'spur of basalt: bazalt çıkıntısı.'}, {'id': 163, 'text': 'He knotted the equipment securely and lowered the bundles down the vertical chimney first.', 'translation': 'Ekipmanları güvenli bir şekilde bağladı ve önce çıkınları dikey bacadan aşağıya indirdi.', 'notes': 'vertical chimney: dikey baca.'}, {'id': 164, 'text': 'Then, one by one, we gripped the double rope with our hands and slid down into the darkness.', 'translation': 'Ardından teker teker ellerimizle çift halatı kavradık ve karanlığın içine doğru aşağıya kaydık.', 'notes': 'slid down into: içine doğru aşağı kaydı.'}, {'id': 165, 'text': 'I felt a terrible dizziness whenever I dared to look down between my swinging boots.', 'translation': 'Sallanan çizmelerimin arasından aşağıya bakmaya her cüret ettiğimde korkunç bir baş dönmesi hissettim.', 'notes': 'terrible dizziness: korkunç baş dönmesi.'}, {'id': 166, 'text': 'Fortunately, the volcanic walls offered occasional rocky ledges where we could pause and rest our aching arms.', 'translation': 'Neyse ki volkanik duvarlar, durup ağrıyan kollarımızı dinlendirebileceğimiz ara sıra kayalık çıkıntılar sunuyordu.', 'notes': 'rocky ledges: kayalık çıkıntılar / setler.'}, {'id': 167, 'text': 'After three exhausting hours of descending, our feet finally touched a firm, sloping floor of solidified lava.', 'translation': 'Üç yorucu iniş saatinin ardından ayaklarımız nihayet katılaşmış lavdan oluşan sağlam ve eğimli bir zemine değdi.', 'notes': 'sloping floor: eğimli zemin.'}, {'id': 168, 'text': 'Above our heads, the opening of the chimney appeared no larger than a tiny twinkling star.', 'translation': 'Başlarımızın üzerinde bacanın ağzı, minik parıldayan bir yıldızdan daha büyük görünmüyordu.', 'notes': 'twinkling star: parıldayan yıldız.'}, {'id': 169, 'text': 'Daylight had vanished completely, leaving us in a world ruled by eternal night.', 'translation': 'Gün ışığı tamamen yok olmuş, bizi ebedi gecenin hüküm sürdüğü bir dünyada bırakmıştı.', 'notes': 'ruled by eternal night: ebedi gecenin hükmettiği.'}, {'id': 170, 'text': 'Hans switched on the Ruhmkorff battery, flooding the subterranean tunnel with a brilliant electric glow.', 'translation': 'Hans Ruhmkorff bataryasını açarak yeraltı tünelini parlak bir elektrik ışıltısıyla aydınlattı.', 'notes': 'flooding with glow: ışıltıyla doldurarak.'}, {'id': 171, 'text': 'The volcanic corridor was magnificent, coated with sparkling crystals of feldspar and shiny obsidian.', 'translation': 'Volkanik koridor muhteşemdi; parıldayan feldispat kristalleri ve parlak obsidyenle kaplanmıştı.', 'notes': 'shiny obsidian: parlak obsidyen.'}, {'id': 172, 'text': '"Look at these basalt walls!" my uncle exclaimed, tapping the rock with his geological hammer.', 'translation': 'Jeoloji çekiciyle kayaya vurarak amcam, "Şu bazalt duvarlara bak!" diye haykırdı.', 'notes': 'geological hammer: jeolog çekici.'}, {'id': 173, 'text': '"They were carved by rivers of molten fire during ancient eruptions thousands of years ago!"', 'translation': '"Binlerce yıl önceki kadim püskürmeler sırasında erimiş ateş nehirleri tarafından oyulmuşlar!"', 'notes': 'rivers of molten fire: erimiş ateş nehirleri.'}, {'id': 174, 'text': 'The passage sloped gently downward at an angle of roughly forty-five degrees toward the southeast.', 'translation': 'Geçit güneydoğuya doğru yaklaşık kırk beş derecelik bir açıyla tatlı tatlı aşağıya doğru eğimleniyordu.', 'notes': 'sloped gently downward: tatlı bir eğimle aşağı indi.'}, {'id': 175, 'text': 'Walking was easy and comfortable on the smooth surface of the cooled magma.', 'translation': 'Soğumuş magmanın pürüzsüz yüzeyinde yürümek kolay ve rahattı.', 'notes': 'cooled magma: soğumuş magma.'}, {'id': 176, 'text': 'To my astonishment, the underground temperature remained remarkably pleasant, registering only fifty-four degrees Fahrenheit.', 'translation': 'Beni hayrete düşürecek şekilde yeraltı sıcaklığı yalnızca 54 Fahrenhayt göstererek dikkate değer ölçüde hoş kaldı.', 'notes': 'remarkably pleasant: dikkate değer biçimde hoş.'}, {'id': 177, 'text': '"You see, Axel," the professor laughed mockingly, "your fears of intolerable subterranean heat are unfounded!"', 'translation': 'Profesör alaycı bir şekilde gülerek, "Gördün mü Axel, dayanılmaz yeraltı ısısı korkuların temelsizmiş!" dedi.', 'notes': 'intolerable heat: dayanılmaz ısı.'}, {'id': 178, 'text': 'I had to admit that his observations contradicted the prevailing thermal theories of contemporary science.', 'translation': 'Onun gözlemlerinin çağdaş bilimin hakim termal teorileriyle çeliştiğini kabul etmek zorundaydım.', 'notes': 'contradicted prevailing theories: hakim teorilerle çelişti.'}, {'id': 179, 'text': "We marched forward for nearly eight hours, penetrating deeper and deeper into the Earth's crust.", 'translation': 'Yerkabuğunun daha ve daha derinlerine nüfuz ederek yaklaşık sekiz saat boyunca ileriye doğru yürüdük.', 'notes': 'penetrating deeper: daha derine nüfuz eden.'}, {'id': 180, 'text': 'When we halted to pitch our first subterranean camp, the barometer indicated a depth of two thousand feet below sea level.', 'translation': 'İlk yeraltı kampımızı kurmak için durduğumuzda barometre deniz seviyesinin iki bin fit altındaki bir derinliği gösteriyordu.', 'notes': 'below sea level: deniz seviyesinin altında.'}]}, {'page_no': 10, 'title': 'The Agony of Thirst in the Depths', 'tr_title': "Su Stoğunun Tükenmesi ve Axel'ın Susuzluktan Bayılması", 'vocab_focus': [('parched', 'kurumuş, kavrulmuş (susuzluktan)'), ('ration', 'tayin, istihkak, porsiyon'), ('dehydration', 'susuzluk, dehidrasyon'), ('agony', 'büyük ıstırap, can çekişme'), ('fork', 'çatallanma, yol ayrımı'), ('despair', 'umutsuzluk, çaresizlik'), ('drought', 'kuraklık, su kıtlığı'), ('exhaustion', 'bitkinlik, dermansızlık')], 'sentences': [{'id': 181, 'text': 'On the fifth day of our descent, our tunnel branched into two distinct passageways at an immense crossroad.', 'translation': 'İnişimizin beşinci gününde tünelimiz devasa bir dörtyol ağzında iki ayrı geçide ayrıldı.', 'notes': 'branched into two: ikiye ayrıldı / çatallandı.'}, {'id': 182, 'text': 'The eastern passage was composed of primitive granite, while the western gallery displayed layers of coal and schist.', 'translation': 'Doğu geçidi ilkel granitten oluşuyordu, batı galerisi ise kömür ve şist katmanları sergiliyordu.', 'notes': 'layers of coal and schist: kömür ve şist katmanları.'}, {'id': 183, 'text': 'My uncle chose the eastern tunnel, convinced that it descended more steeply toward the core.', 'translation': 'Amcam çekirdeğe doğru daha dik indiğine inanarak doğu tünelini seçti.', 'notes': 'descended more steeply: daha dik indi.'}, {'id': 184, 'text': 'Unfortunately, after three days of marching, this route led us into a dead end blocked by solid rock.', 'translation': 'Ne yazık ki üç günlük yürüyüşün ardından bu rota bizi sert kayayla tıkanmış çıkmaz bir yola götürdü.', 'notes': 'dead end blocked by: ...ile tıkanmış çıkmaz yol.'}, {'id': 185, 'text': 'We had wasted precious time and physical energy exploring a completely useless subterranean gallery.', 'translation': 'Tamamen yararsız bir yeraltı galerisini keşfederek değerli zamanımızı ve fiziksel enerjimizi boşa harcamıştık.', 'notes': 'wasted precious time: değerli zamanı boşa harcadı.'}, {'id': 186, 'text': 'Even worse, during this futile detour our water supply had diminished at an alarming rate.', 'translation': 'Daha da kötüsü, bu nafile sapma sırasında su stoğumuz korkutucu bir hızla azalmıştı.', 'notes': 'diminished at an alarming rate: endişe verici bir hızla azaldı.'}, {'id': 187, 'text': 'We had counted on finding subterranean springs or streams, but the volcanic rock was completely dry.', 'translation': 'Yeraltı pınarları ya da dereleri bulacağımıza güvenmiştik ama volkanik kaya tamamen kuruydu.', 'notes': 'counted on finding: bulmaya güvenmiştik / bel bağlamıştık.'}, {'id': 188, 'text': 'We were forced to retrace our steps back to the fork, suffering under heavy backpacks.', 'translation': 'Ağır sırt çantalarının altında acı çekerek çatala kadar adımlarımızı geri izlemek zorunda kaldık.', 'notes': 'retrace steps: adımlarını gerisin geri takip etmek.'}, {'id': 189, 'text': 'By the eighth of July, the last drop of water had been drained from our leather flasks.', 'translation': "8 Temmuz'a gelindiğinde deri mataralarımızdaki son su damlası da tükenmişti.", 'notes': 'last drop drained: son damla da tüketildi.'}, {'id': 190, 'text': 'My throat burned like glowing embers, and my tongue swelled so severely that I could hardly swallow.', 'translation': 'Boğazım kor közler gibi yanıyordu ve dilim o kadar şiddetli şişmişti ki neredeyse yutkunamıyordum.', 'notes': 'swelled severely: şiddetle şişti.'}, {'id': 191, 'text': '"Uncle, I can go no further," I gasped, sinking down onto the stony ground with tears in my eyes.', 'translation': 'Gözlerimde yaşlarla taşlı zemine yığılarak, "Amca, daha fazla gidemeyeceğim," diye soludum.', 'notes': 'sinking down onto: üzerine yığılarak.'}, {'id': 192, 'text': '"Let us turn back before we perish of thirst in this terrible tomb!"', 'translation': '"Bu korkunç mezarda susuzluktan can vermeden önce geri dönelim!"', 'notes': 'perish of thirst: susuzluktan can vermek.'}, {'id': 193, 'text': 'Professor Lidenbrock looked at me with deep sorrow and knelt beside my trembling body.', 'translation': 'Profesör Lidenbrock derin bir kederle bana baktı ve titreyen vücudumun yanında diz çöktü.', 'notes': 'knelt beside: yanında diz çöktü.'}, {'id': 194, 'text': 'He pulled a small flask from his coat—a reserve he had kept untouched for a moment of extreme extremity.', 'translation': 'Ceketinden küçük bir matara çıkardı—son derece kritik bir an için el sürmeden sakladığı bir ihtiyat stoğu.', 'notes': 'extreme extremity: aşırı acil durum / son radde.'}, {'id': 195, 'text': '"Drink this, Axel," he murmured gently, pouring the last few drops between my parched lips.', 'translation': 'Son birkaç damlayı kavrulmuş dudaklarımın arasına dökerek, "Bunu iç Axel," diye usulca mırıldandı.', 'notes': 'parched lips: kurumuş / çatlamış dudaklar.'}, {'id': 196, 'text': 'The liquid restored a brief glimmer of life to my veins, but I realized that my uncle had deprived himself entirely.', 'translation': 'Sıvı damarlarıma kısa bir hayat parıltısı kazandırdı ama amcamın kendini bundan tamamen mahrum bıraktığını fark ettim.', 'notes': 'deprived himself entirely: kendini tamamen mahrum bıraktı.'}, {'id': 197, 'text': '"If we do not find water within twenty-four hours," he promised gravely, "I will agree to return to the surface."', 'translation': 'Ciddiyetle, "Eğer yirmi dört saat içinde su bulamazsak," diye söz verdi, "yeryüzüne dönmeyi kabul edeceğim."', 'notes': 'agreed to return: dönmeyi kabul etti.'}, {'id': 198, 'text': 'Hans stood silently in the shadows, listening intently to the massive rock walls surrounding us.', 'translation': 'Hans gölgelerin içinde sessizce duruyor, bizi çevreleyen devasa kaya duvarlarını dikkatle dinliyordu.', 'notes': 'listening intently: can kulağıyla dinleyen.'}, {'id': 199, 'text': 'Suddenly, without uttering a single word, the guide picked up his pickaxe and walked away into the dark corridor.', 'translation': 'Aniden tek bir kelime bile etmeden rehber kazmasını aldı ve karanlık koridorun içine doğru yürüdü.', 'notes': 'without uttering a word: tek kelime etmeksizin.'}, {'id': 200, 'text': 'I closed my eyes in utter exhaustion, wondering if our loyal companion had decided to abandon us to our fate.', 'translation': 'Sadık yoldaşımızın bizi kaderimize terk etmeye mi karar verdiğini merak ederek tam bir tükenmişlik içinde gözlerimi kapattım.', 'notes': 'abandon us to our fate: bizi kaderimize terk etmek.'}]}, {'page_no': 11, 'title': 'Hans Taps the Subterranean Torrent', 'tr_title': "Hans'ın Kayayı Delmesi: Kaynar Ama Hayat Kurtaran Hansbach Deresi", 'vocab_focus': [('torrent', 'gürül gürül akan su, çağlayan'), ('pickaxe', 'kazma'), ('artesian', 'artezyen (kaynaktan fışkıran)'), ('scalding', 'kaynar, yakıcı sıcaklıkta'), ('revive', 'yeniden canlandırmak, hayata döndürmek'), ('miraculous', 'mucizevi'), ('companion', 'yoldaş, refakatçi'), ('gratitude', 'minnettarlık, şükran')], 'sentences': [{'id': 201, 'text': 'Nearly an hour passed before the steady scraping of footsteps announced the return of our Icelandic guide.', 'translation': 'Ayak seslerinin düzenli sürtünmesi İzlandalı rehberimizin dönüşünü haber vermeden önce neredeyse bir saat geçti.', 'notes': 'scraping of footsteps: ayak seslerinin sürtünmesi.'}, {'id': 202, 'text': 'Hans approached my uncle and uttered a single word in his calm, resonant voice: "Vatten!"', 'translation': 'Hans amcama yaklaştı ve sakin, yankılı sesiyle tek bir kelime söyledi: "Vatten!"', 'notes': 'uttered a single word: tek bir kelime söyledi.'}, {'id': 203, 'text': '"Water!" my uncle yelled, leaping up with a vitality that seemed impossible for a starving man.', 'translation': 'Açlıktan bitap düşmüş bir adam için imkansız görünen bir canlılıkla ayağa fırlayarak amcam, "Su!" diye bağırdı.', 'notes': 'leaping up with vitality: canlılıkla ayağa fırlayarak.'}, {'id': 204, 'text': 'We hurried after Hans along the western gallery, whose steep incline plunged deeper into the Earth.', 'translation': "Dik eğimi Dünya'nın daha derinlerine inen batı galerisi boyunca Hans'ın peşinden koştuk.", 'notes': 'steep incline plunged: dik eğim derine indi.'}, {'id': 205, 'text': 'After walking about a hundred paces, Hans stopped beside a solid granite wall and placed his ear against it.', 'translation': 'Yaklaşık yüz adım yürüdükten sonra Hans sert bir granit duvarın yanında durdu ve kulağını duvara dayadı.', 'notes': 'placed his ear against: kulağını ...e dayadı.'}, {'id': 206, 'text': 'I pressed my ear to the cold stone and heard a distinct, muffled roaring behind the rock.', 'translation': 'Kulağımı soğuk taşa bastırdım ve kayanın arkasında boğuk, belirgin bir kükreme duydum.', 'notes': 'muffled roaring: boğuk bir kükreme.'}, {'id': 207, 'text': 'A powerful underground river was flowing swiftly through the hidden layers only a few feet away from us.', 'translation': 'Güçlü bir yeraltı nehri, bizden yalnızca birkaç fit uzaktaki gizli katmanlar arasından hızla akıyordu.', 'notes': 'flowing swiftly: hızla akıyordu.'}, {'id': 208, 'text': 'Hans gripped his heavy iron pickaxe and began striking the impenetrable rock with steady, rhythmic blows.', 'translation': 'Hans ağır demir kazmasını kavradı ve düzenli, ritmik darbelerle geçit vermez kayaya vurmaya başladı.', 'notes': 'striking with steady blows: düzenli darbelerle vurarak.'}, {'id': 209, 'text': 'Sparks flew in showers from the contact of steel against quartz, illuminating his determined expression.', 'translation': 'Çeliğin kuvarssa çarpmasından kıvılcımlar saçılıyor, onun kararlı yüz ifadesini aydınlatıyordu.', 'notes': 'sparks flew in showers: sağanak halinde kıvılcımlar saçıldı.'}, {'id': 210, 'text': 'For nearly two grueling hours, the patient hunter chipped away at the stubborn barrier.', 'translation': 'Neredeyse iki zorlu saat boyunca sabırlı avcı inatçı engeli yavaş yavaş yonttu.', 'notes': 'chipped away at: parça parça oyup yonttu.'}, {'id': 211, 'text': 'Suddenly, a sharp hiss resonated through the tunnel, followed by a violent fracture in the stone.', 'translation': 'Aniden tünelde keskin bir tıslama yankılandı, ardından taşta şiddetli bir kırılma meydana geldi.', 'notes': 'sharp hiss resonated: keskin bir tıslama yankılandı.'}, {'id': 212, 'text': "A boiling jet of water burst through the fissure, knocking the heavy pickaxe from the guide's hands.", 'translation': 'Kaynayan bir su fışkırması çatlaktan dışarı fırladı ve ağır kazmayı rehberin ellerinden düşürdü.', 'notes': 'boiling jet of water: kaynayan tazyikli su jeti.'}, {'id': 213, 'text': 'Hans let out a sharp cry of pain because the scalding torrent hit his bare arms directly.', 'translation': 'Hans keskin bir acı çığlığı attı çünkü kaynar çağlayan doğrudan çıplak kollarına çarpmıştı.', 'notes': 'let out a sharp cry: acı bir çığlık attı.'}, {'id': 214, 'text': '"The water is boiling hot!" I screamed in despair, feeling our salvation turn into a cruel mockery.', 'translation': 'Kurtuluşumuzun acımasız bir alaya dönüştüğünü hissederek, "Su kaynar sıcaklıkta!" diye çaresizlikle bağırdım.', 'notes': 'salvation turned into mockery: kurtuluş alaya dönüştü.'}, {'id': 215, 'text': '"Patience, my boy!" the professor shouted above the roaring jet. "It will cool quickly in the cold air of the tunnel!"', 'translation': 'Profesör kükreyen suyun üzerinden bağırarak, "Sabret oğlum! Tünelin soğuk havasında hızla soğuyacaktır!" dedi.', 'notes': 'shouted above the roaring jet: kükreyen tazyikin üzerinden haykırdı.'}, {'id': 216, 'text': 'The boiling stream cascaded along the stony floor, giving off thick clouds of fragrant steam.', 'translation': 'Kaynar dere, taşlı zemin boyunca çağladı ve kalın hoş kokulu buhar bulutları yaydı.', 'notes': 'cascaded along: boyunca çağlayarak aktı.'}, {'id': 217, 'text': 'Within minutes, the rushing water cooled to a drinkable temperature, rich with mineral salts.', 'translation': 'Birkaç dakika içinde akan su, mineral tuzları bakımından zengin, içilebilir bir sıcaklığa kadar soğudu.', 'notes': 'rich with mineral salts: mineral tuzları açısından zengin.'}, {'id': 218, 'text': 'I threw myself on my knees and drank greedily, feeling absolute rebirth rush through every fiber of my being.', 'translation': 'Dizlerimin üzerine kapandım ve açgözlülükle içtim; varlığımın her lifinde tam bir yeniden doğuşun aktığını hissettim.', 'notes': 'drank greedily: kana kana / açgözlülükle içti.'}, {'id': 219, 'text': 'It was the most delicious nectar that had ever touched human lips, restoring our strength and courage.', 'translation': 'İnsan dudaklarına değmiş en lezzetli nektardı; gücümüzü ve cesaretimizi yerine getirdi.', 'notes': 'restoring strength: gücü yeniden kazandırmak.'}, {'id': 220, 'text': '"We shall name this blessed stream the Hansbach!" my uncle declared, honoring the loyal man who had saved our lives.', 'translation': 'Amcam hayatlarımızı kurtaran sadık adamı onurlandırarak, "Bu kutsal dereye Hansbach adını vereceğiz!" diye ilan etti.', 'notes': 'name this blessed stream: bu mübarek dereyi adlandırmak.'}]}, {'page_no': 12, 'title': 'Vast Strata of Coal and Ancient Fossils', 'tr_title': 'Yerin Kilometrelerce Altında Dev Kömür ve Fosil Katmanları', 'vocab_focus': [('stratum', 'katman, tabaka'), ('geological', 'jeolojik'), ('fossilized', 'fosilleşmiş'), ('combustible', 'yanıcı, tutuşabilir'), ('carboniferous', 'karbonifer dönemi, taş kömürü çağı'), ('imprint', 'iz, baskı'), ('vegetation', 'bitki örtüsü'), ('subterranean', 'yer altı')], 'sentences': [{'id': 221, 'text': 'With our thirst conquered, our expedition continued downward alongside the cheerful murmur of the Hansbach.', 'translation': "Susuzluğumuzu yenerek keşif heyetimiz Hansbach'ın neşeli şırıltısı eşliğinde aşağıya doğru yoluna devam etti.", 'notes': 'cheerful murmur: neşeli şırıltı.'}, {'id': 222, 'text': 'The stream served as our faithful guide, preventing us from losing our way in the branching labyrinths.', 'translation': 'Dere, dallara ayrılan labirentlerde yolumuzu kaybetmemizi önleyen sadık rehberimiz oldu.', 'notes': 'branching labyrinths: dallanan labirentler.'}, {'id': 223, 'text': 'On the tenth of July, we entered a geological zone that filled my uncle with professional delight.', 'translation': "10 Temmuz'da amcamı mesleki bir sevinçle dolduran bir jeolojik bölgeye girdik.", 'notes': 'professional delight: mesleki sevinç.'}, {'id': 224, 'text': 'The granite walls gave way to sedimentary rock and enormous beds of carboniferous coal.', 'translation': 'Granit duvarlar yerini tortul kayalara ve devasa karbonifer kömür yataklarına bıraktı.', 'notes': 'carboniferous coal: taş kömürü çağı kömürü.'}, {'id': 225, 'text': 'We were traversing the monumental cemetery of primeval forests that had flourished millions of years ago.', 'translation': 'Milyonlarca yıl önce serpilmiş ilkel ormanların anıtsal mezarlığının içinden geçiyorduk.', 'notes': 'primeval forests: ilkel / ilkçağ ormanları.'}, {'id': 226, 'text': 'The walls of the corridor were studded with beautiful imprints of ancient ferns, lycopods, and sigillaria.', 'translation': 'Koridorun duvarları kadim eğrelti otlarının, kibrit otlarının ve mühür ağaçlarının güzel izleriyle bezenmişti.', 'notes': 'studded with imprints: izlerle bezenmiş.'}, {'id': 227, 'text': 'Every detail of their delicate leaves was preserved in the dark shale with astonishing perfection.', 'translation': 'Narin yapraklarının her ayrıntısı koyu renkli killi şist üzerinde şaşırtıcı bir kusursuzlukla korunmuştu.', 'notes': 'astonishing perfection: şaşırtıcı kusursuzluk.'}, {'id': 228, 'text': '"Think of the immense pressure required to turn living trees into these mineral seams!" the professor remarked.', 'translation': 'Profesör, "Canlı ağaçları bu maden damarlarına dönüştürmek için gereken muazzam basıncı bir düşün!" dedi.', 'notes': 'mineral seams: maden damarları.'}, {'id': 229, 'text': 'Here lay enough combustible material to supply all the industrial factories of Europe for centuries.', 'translation': "Burada Avrupa'nın tüm sanayi fabrikalarını yüzyıllar boyu besleyecek kadar yanıcı madde yatıyordu.", 'notes': 'combustible material: yanıcı madde.'}, {'id': 230, 'text': 'However, this underground coalfield presented a deadly hazard known to miners as firedamp.', 'translation': 'Ancak bu yeraltı kömür havzası, madencilerin grizu olarak bildiği ölümcül bir tehlike barındırıyordu.', 'notes': 'deadly hazard: ölümcül tehlike.'}, {'id': 231, 'text': 'Invisible pockets of carbureted hydrogen gas could detonate into a devastating fireball at the slightest spark.', 'translation': 'Görünmez hidrokarbon gaz cepleri en ufak bir kıvılcımda yıkıcı bir ateş topuna dönüşerek patlayabilirdi.', 'notes': 'detonate into a fireball: ateş topu halinde patlamak.'}, {'id': 232, 'text': 'Our Ruhmkorff electric apparatus proved to be our greatest blessing, producing cold light without an open flame.', 'translation': 'Ruhmkorff elektrik aygıtımız açık alev olmadan soğuk ışık üreterek en büyük nimetimiz oldu.', 'notes': 'greatest blessing: en büyük nimet.'}, {'id': 233, 'text': 'As we descended deeper, the fossil remains evolved from simple plants to primitive animal life.', 'translation': 'Daha da derine indikçe fosil kalıntıları basit bitkilerden ilkel hayvan yaşamına doğru evrildi.', 'notes': 'fossil remains evolved: fosil kalıntıları evrildi.'}, {'id': 234, 'text': 'I examined petrified shells, trilobites, and the skeletal fragments of ancient armored fishes.', 'translation': 'Taşlaşmış kabukları, trilobitleri ve kadim zırhlı balıkların iskelet parçalarını inceledim.', 'notes': 'petrified shells: taşlaşmış kabuklar.'}, {'id': 235, 'text': 'We were literally walking backward through the great pages of biological history.', 'translation': 'Kelimenin tam anlamıyla biyoloji tarihinin büyük sayfaları arasında zamanda geriye doğru yürüyorduk.', 'notes': 'walking backward through: ...içinde geriye doğru yürümek.'}, {'id': 236, 'text': 'My scientific skepticism gradually gave way to unbounded wonder and admiration.', 'translation': 'Bilimsel şüpheciliğim yavaş yavaş yerini sınırsız bir hayret ve hayranlığa bıraktı.', 'notes': 'unbounded wonder: sınırsız hayret.'}, {'id': 237, 'text': 'The subterranean atmosphere remained dense and heavy, but entirely breathable.', 'translation': 'Yeraltı atmosferi yoğun ve ağır kaldı ama tamamen solunabilir durumdaydı.', 'notes': 'dense and heavy: yoğun ve ağır.'}, {'id': 238, 'text': 'By calculating our barometer readings, my uncle announced that we were now thirty leagues below Iceland.', 'translation': "Barometre okumalarımızı hesaplayan amcam, şu anda İzlanda'nın otuz fersah altında olduğumuzu duyurdu.", 'notes': 'thirty leagues below: otuz fersah altında.'}, {'id': 239, 'text': 'That meant we were positioned directly beneath the crushing weight of the Atlantic Ocean.', 'translation': "Bu, doğrudan Atlantik Okyanusu'nun ezici ağırlığının tam altında bulunduğumuz anlamına geliyordu.", 'notes': 'crushing weight: ezici ağırlık.'}, {'id': 240, 'text': 'The thought that millions of tons of water hung above our heads caused an icy shiver to run down my spine.', 'translation': 'Tepemizde milyonlarca ton suyun asılı durduğu düşüncesi omurgamdan aşağı buz gibi bir ürperti geçirdi.', 'notes': 'icy shiver ran down spine: omurgasından buz gibi bir ürperti geçti.'}]}, {'page_no': 13, 'title': 'Lost in the Labyrinth and the Acoustic Miracle', 'tr_title': "Axel'ın Labirentte Kaybolması ve Akustik Duvar Sayesinde Sesle Bulunma", 'vocab_focus': [('labyrinth', 'labirent'), ('separated', 'ayrılmış, kopmuş'), ('echo', 'yankı'), ('acoustic', 'akustik, ses iletimine ait'), ('panic', 'panik, dehşet'), ('suffocation', 'boğulma'), ('hallucination', 'halüsinasyon, sanrı'), ('reunion', 'yeniden kavuşma, buluşma')], 'sentences': [{'id': 241, 'text': 'On the twelfth of July, a dreadful accident plunged me into the darkest nightmare of my life.', 'translation': "12 Temmuz'da korkunç bir kaza beni hayatımın en karanlık kabusunun içine fırlattı.", 'notes': 'plunged into nightmare: kabusun içine sürükledi.'}, {'id': 242, 'text': 'I had walked ahead of the party, carrying one of the Ruhmkorff lamps to inspect an interesting rock formation.', 'translation': 'İlginç bir kaya oluşumunu incelemek için Ruhmkorff lambalarından birini taşıyarak grubun önünden yürümüştüm.', 'notes': 'walked ahead of: grubun önünden yürüdü.'}, {'id': 243, 'text': 'Entranced by a glittering vein of gold, I failed to notice a turning where the tunnel divided.', 'translation': 'Parıldayan bir altın damarına kendimi kaptırarak tünelin bölündüğü bir dönemeci fark edemedim.', 'notes': 'entranced by: ...ile büyülenmiş / kendinden geçmiş.'}, {'id': 244, 'text': 'When I turned around to show the specimen to my uncle, I found myself in absolute, terrifying solitude.', 'translation': 'Örneği amcama göstermek için arkamı döndüğümde, kendimi mutlak ve korkunç bir yalnızlık içinde buldum.', 'notes': 'absolute solitude: mutlak yalnızlık.'}, {'id': 245, 'text': '"Uncle! Hans!" I shouted, but only hollow echoes replied from the gloomy galleries.', 'translation': '"Amca! Hans!" diye bağırdım ama kasvetli galerilerden yalnızca yankılanan boğuk sesler cevap verdi.', 'notes': 'hollow echoes: boş / boğuk yankılar.'}, {'id': 246, 'text': 'Even more horrifying, the familiar murmur of the Hansbach had disappeared; I had strayed away from the water.', 'translation': "Daha da korkuncu, Hansbach'ın o tanıdık şırıltısı kaybolmuştu; sudan uzaklaşmıştım.", 'notes': 'strayed away from: ...den uzağa sapmıştı.'}, {'id': 247, 'text': 'In a frantic frenzy of panic, I ran blindly backward through the darkness, tripping over jagged boulders.', 'translation': 'Çılgınca bir panik hezeyanıyla sivri kayalara takılarak karanlığın içinde körlemesine geriye koştum.', 'notes': 'ran blindly: körlemesine koştu.'}, {'id': 248, 'text': 'I stumbled and fell heavily, shattering my lantern against the sharp stone floor.', 'translation': 'Tökezleyip sertçe düştüm ve fenerimi keskin taş zemine çarparak paramparça ettim.', 'notes': 'shattering my lantern: fenerimi paramparça ederek.'}, {'id': 249, 'text': 'Instant, impenetrable blackness enveloped me—a darkness so thick that it seemed to weigh upon my eyelids.', 'translation': 'Anında, geçit vermez bir zifiri karanlık beni sardı—göz kapaklarıma ağırlık yapacak kadar koyu bir karanlık.', 'notes': 'impenetrable blackness: içine girilemez zifiri karanlık.'}, {'id': 250, 'text': 'I lay bleeding on the rocks, weeping uncontrollably and suffocating in the stagnant subterranean air.', 'translation': 'Kayaların üzerinde kanlar içinde yattım, kontrolsüzce ağladım ve durgun yeraltı havasında boğulur gibi oldum.', 'notes': 'stagnant air: durgun / havasız hava.'}, {'id': 251, 'text': 'Hours passed, and madness began to creep into my feverish mind with terrifying hallucinations.', 'translation': 'Saatler geçti ve delilik korkunç halüsinasyonlarla ateşli zihnime süzülmeye başladı.', 'notes': 'madness crept into: delilik içine süzüldü.'}, {'id': 252, 'text': 'Suddenly, through the dense silence, a faint vibrating whisper brushed against the rock wall near my head.', 'translation': 'Aniden o yoğun sessizliğin içinden, başımın yanındaki kaya duvara hafifçe çarpan titreşimli bir fısıltı geçti.', 'notes': 'vibrating whisper: titreşen fısıltı.'}, {'id': 253, 'text': 'I pressed my ear against the stone, holding my breath so hard that my lungs ached.', 'translation': 'Kulağımı taşa bastırdım, nefesimi ciğerlerimi ağrıtacak kadar sımsıkı tuttum.', 'notes': 'holding my breath: nefesini tutarak.'}, {'id': 254, 'text': '"Axel! Axel! Can you hear me?" my uncle\'s voice traveled clearly through the granite stratum.', 'translation': 'Granit tabakanın içinden amcamın sesi net bir şekilde ulaştı: "Axel! Axel! Beni duyabiliyor musun?"', 'notes': 'voice traveled clearly: ses net bir şekilde ulaştı.'}, {'id': 255, 'text': 'The dense rock acted like an immense acoustic tube, conducting sound waves over great distances.', 'translation': 'Yoğun kaya, ses dalgalarını büyük mesafeler boyunca ileten devasa bir akustik tüp gibi işlev görüyordu.', 'notes': 'acoustic tube: akustik tüp / ses borusu.'}, {'id': 256, 'text': '"Uncle! I am lost in the dark!" I cried back against the wall with all the strength left in my body.', 'translation': 'Vücudumda kalan tüm güçle duvara doğru, "Amca! Karanlıkta kayboldum!" diye haykırdım.', 'notes': 'cried back: karşılık vererek bağırdı.'}, {'id': 257, 'text': '"Do not despair!" the voice replied. "Hans and I are descending toward you! Follow the sound of my chronometer!"', 'translation': 'Ses, "Umudunu kaybetme!" diye yanıtladı. "Hans ve ben sana doğru iniyoruz! Kronometremin sesini takip et!"', 'notes': 'do not despair: umudunu yitirme.'}, {'id': 258, 'text': 'He instructed me to crawl down the slope, calculating our separation at less than eight hundred yards.', 'translation': 'Aramızdaki mesafeyi sekiz yüz yardadan daha az hesaplayarak eğimden aşağı sürünmemi tembihledi.', 'notes': 'crawl down the slope: yamaçtan aşağı sürünmek.'}, {'id': 259, 'text': 'I crawled on my hands and knees in the pitch dark until the ground suddenly dropped from beneath me.', 'translation': 'Zemin birdenbire altımdan kaybolana kadar zifiri karanlıkta ellerimin ve dizlerimin üzerinde süründüm.', 'notes': 'ground suddenly dropped: yer birden altından kaydı.'}, {'id': 260, 'text': 'I plummeted into an open void, losing consciousness just as strong arms caught me in midair.', 'translation': 'Güçlü kollar beni havada tam yakalarken bilincimi kaybederek açık bir boşluğa yuvarlandım.', 'notes': 'plummeted into an open void: açık bir boşluğa yuvarlandı.'}]}, {'page_no': 14, 'title': 'The Vast Subterranean Ocean and Luminous Sky', 'tr_title': "Büyük Boşluğa Açılış: Yeraltı Akdeniz'i ve Elektrikli Gökyüzü", 'vocab_focus': [('luminous', 'ışık saçan, aydınlık'), ('subterranean', 'yer altı'), ('horizon', 'ufuk'), ('aurora', 'kutup ışığı, parıltı'), ('ocean', 'okyanus, umman'), ('phenomenon', 'fenomen, doğa olayı'), ('boundless', 'sınırsız, uçsuz bucaksız'), ('tide', 'gelgit, medcezir')], 'sentences': [{'id': 261, 'text': 'When I opened my eyes, I thought I had awakened in an enchanted fairy kingdom.', 'translation': 'Gözlerimi açtığımda büyülü bir peri krallığında uyandığımı sandım.', 'notes': 'enchanted kingdom: büyülü krallık.'}, {'id': 262, 'text': 'I was lying on a bed of fine yellow sand, bathed in a soft, silvery radiance that had no visible source.', 'translation': 'Görünür hiçbir kaynağı olmayan yumuşak, gümüşi bir ışıltıyla yıkanan ince sarı kumdan bir yatakta yatıyordum.', 'notes': 'bathed in silvery radiance: gümüşi ışıltıyla yıkanmış.'}, {'id': 263, 'text': 'My uncle was gently dressing the wound on my forehead with clean bandages and soothing ointments.', 'translation': 'Amcam alnımdaki yarayı temiz sargı bezleri ve yatıştırıcı merhemlerle nazikçe sarıyordu.', 'notes': 'soothing ointments: yatıştırıcı merhemler.'}, {'id': 264, 'text': '"Axel, my dear boy, you are alive!" he cried, embracing me with tears streaming down his rugged cheeks.', 'translation': 'Pürüzlü yanaklarından yaşlar süzülerek bana sarılıp, "Axel, canım oğlum, hayattasın!" diye haykırdı.', 'notes': 'rugged cheeks: pürüzlü / sert hatlı yanaklar.'}, {'id': 265, 'text': 'Hans stood nearby, boiling dried meat over a small alcohol burner with his customary calmness.', 'translation': 'Hans her zamanki sakinliğiyle küçük bir ispirto ocağında kurutulmuş et haşlayarak yakında duruyordu.', 'notes': 'customary calmness: her zamanki sakinlik.'}, {'id': 266, 'text': 'I sat up slowly and looked around, completely overwhelmed by the breathtaking spectacle before me.', 'translation': 'Yavaşça doğruldum ve etrafıma baktım; önümdeki nefes kesici manzara karşısında tamamen büyülendim.', 'notes': 'breathtaking spectacle: nefes kesici manzara.'}, {'id': 267, 'text': 'We were standing on the shore of an immense body of water that stretched to a distant horizon.', 'translation': 'Uzak bir ufka kadar uzanan devasa bir su kütlesinin kıyısında duruyorduk.', 'notes': 'body of water: su kütlesi.'}, {'id': 268, 'text': 'Gentle waves were breaking with a soft, rhythmic whisper upon a wide beach of golden sand.', 'translation': 'Tatlı dalgalar altın rengi kumdan geniş bir kumsala yumuşak, ritmik bir fısıltıyla vuruyordu.', 'notes': 'breaking upon the beach: sahile vuruyordu.'}, {'id': 269, 'text': '"Is that the ocean?" I whispered, unable to believe my senses.', 'translation': 'Duyularıma inanamayarak, "O bir okyanus mu?" diye fısıldadım.', 'notes': 'unable to believe senses: duyularına inanamayarak.'}, {'id': 270, 'text': '"It is a subterranean sea," my uncle replied proudly, "and I have christened it the Central Sea!"', 'translation': 'Amcam gururla, "Bu bir yeraltı denizidir," diye yanıtladı, "ve ben onu Merkez Denizi olarak vaftiz ettim!"', 'notes': 'christened it: onu adlandırdı / vaftiz etti.'}, {'id': 271, 'text': 'High above our heads arched an enormous granite vault, towering thousands of feet into the air.', 'translation': 'Başlarımızın çok yukarısında havaya binlerce fit yükselen devasa bir granit kubbe kavis çiziyordu.', 'notes': 'granite vault: granit tonoz / kubbe.'}, {'id': 272, 'text': 'The entire cavern was illuminated by an electric phenomenon similar to the aurora borealis.', 'translation': 'Mağaranın tamamı kutup ışıklarına benzeyen elektriksel bir doğa olayıyla aydınlanıyordu.', 'notes': 'aurora borealis: kuzey ışıkları / kutup ışıkları.'}, {'id': 273, 'text': 'Luminous vapors hung beneath the rocky ceiling, diffusing a continuous, clear, and shadowless daylight.', 'translation': 'Işık saçan buharlar kayalık tavanın altında asılı duruyor; kesintisiz, berrak ve gölgesiz bir gün ışığı yayıyordu.', 'notes': 'luminous vapors: ışık saçan buharlar.'}, {'id': 274, 'text': 'Dense clouds of vapor moved across this artificial sky, carried by mysterious underground winds.', 'translation': 'Yoğun buhar bulutları gizemli yeraltı rüzgarlarıyla taşınarak bu yapay gökyüzünde süzülüyordu.', 'notes': 'artificial sky: yapay gökyüzü.'}, {'id': 275, 'text': 'The sea was truly vast; neither binoculars nor our keenest gaze could discover the opposite shore.', 'translation': 'Deniz gerçekten uçsuz bucaksızdı; ne dürbünlerimiz ne de en keskin bakışlarımız karşı kıyıyı keşfedebildi.', 'notes': 'opposite shore: karşı kıyı.'}, {'id': 276, 'text': 'The air was crisp and revitalizing, filled with the unmistakable salty fragrance of the sea.', 'translation': 'Hava serinletici ve tazelik vericiydi, denizin o belirgin tuzlu kokusuyla doluydu.', 'notes': 'unmistakable salty fragrance: belirgin tuzlu koku.'}, {'id': 277, 'text': 'Looking at the water line, I noticed that the tide was currently rising along the sandy beach.', 'translation': 'Su çizgisine bakarak medcezrin kumsal boyunca şu anda yükselmekte olduğunu fark ettim.', 'notes': 'tide was rising: gelgit yükseliyordu.'}, {'id': 278, 'text': "Even down here, thirty-five leagues below the Earth's surface, the lunar pull governed the motion of the waters.", 'translation': 'Burada bile, Yerkürenin yüzeyinin otuz beş fersah altında ayın çekim gücü suların hareketini yönetiyordu.', 'notes': 'lunar pull governed: ayın çekimi yönetti.'}, {'id': 279, 'text': 'We were standing inside a wondrous subterranean world that no living mortal had ever witnessed.', 'translation': 'Daha önce yaşayan hiçbir ölümlünün tanık olmadığı harika bir yeraltı dünyasının içinde duruyorduk.', 'notes': 'living mortal: yaşayan fani / ölümlü.'}, {'id': 280, 'text': '"Arne Saknussemm came this way," my uncle whispered with awe. "And we shall cross this ocean to follow him!"', 'translation': 'Amcam huşu içinde, "Arne Saknussemm bu yoldan geçmişti," diye fısıldadı. "Ve biz onu takip etmek için bu okyanusu aşacağız!"', 'notes': 'whispered with awe: huşu içinde fısıldadı.'}]}, {'page_no': 15, 'title': 'The Forest of Giant Mushrooms and Primeval Flora', 'tr_title': 'Dev Mantarlar Ormanı ve Tarih Öncesi Bitki Örtüsü', 'vocab_focus': [('mushroom', 'mantar'), ('gigantic', 'devasa, devasa büyüklükte'), ('vegetation', 'bitki örtüsü, flora'), ('specimen', 'örnek, numune'), ('botanical', 'botanik, bitkibilimsel'), ('fungus', 'mantar (biyolojik cins)'), ('petrified', 'taşlaşmış'), ('canopy', 'gölgelik, ağaç tepesi örtüsü')], 'sentences': [{'id': 281, 'text': 'Behind the golden beach, a strange and eerie forest rose toward the distant cliffs.', 'translation': 'Altın kumsalın ardında, garip ve tekinsiz bir orman uzak kayalıklara doğru yükseliyordu.', 'notes': 'eerie forest: tekinsiz / tekinsiz orman.'}, {'id': 282, 'text': 'My uncle and I walked toward it, eager to examine this unexpected subterranean vegetation.', 'translation': 'Amcam ve ben, bu beklenmedik yeraltı bitki örtüsünü incelemek için can atarak oraya doğru yürüdük.', 'notes': 'eager to examine: incelemeye hevesli.'}, {'id': 283, 'text': 'As we approached, I stopped dead in my tracks, rubbing my eyes in utter disbelief.', 'translation': 'Yaklaştığımızda tam bir inançsızlık içinde gözlerimi ovuşturarak olduğum yerde kalakaldım.', 'notes': 'stopped dead in tracks: olduğu yerde kalakaldı.'}, {'id': 284, 'text': 'The trees were not oaks, pines, or maples, but gigantic mushrooms standing thirty to forty feet high!', 'translation': 'Ağaçlar meşe, çam ya da akçaağaç değil; otuz ila kırk fit yüksekliğinde duran devasa mantarlardı!', 'notes': 'gigantic mushrooms: devasa mantarlar.'}, {'id': 285, 'text': 'Their massive white stalks supported enormous circular umbrellas that shaded hundreds of square yards.', 'translation': 'Devasa beyaz gövdeleri, yüzlerce metrekareyi gölgeleyen koskoca dairesel şemsiyeleri taşıyordu.', 'notes': 'massive white stalks: devasa beyaz gövdeler.'}, {'id': 286, 'text': 'They were gigantic specimens of Lycoperdon giganteum, thriving in the warm, humid air of the cavern.', 'translation': 'Mağaranın ılık ve nemli havasında serpilip büyüyen devasa Lycoperdon giganteum örnekleriydi bunlar.', 'notes': 'thriving in humid air: nemli havada serpilip büyüyen.'}, {'id': 287, 'text': '"Behold the flora of the primary era!" Professor Lidenbrock cried, touching the spongy white bark with awe.', 'translation': 'Süngerimsi beyaz kabuğa huşuyla dokunarak Profesör Lidenbrock, "Birinci zamanın bitki örtüsüne bakın!" diye haykırdı.', 'notes': 'spongy white bark: süngerimsi beyaz kabuk.'}, {'id': 288, 'text': 'Thousands of these fungal colossi formed endless avenues beneath the glowing electrical ceiling.', 'translation': 'Bu mantar devlerinden binlercesi, parıldayan elektrikli tavanın altında uçsuz bucaksız caddeler oluşturuyordu.', 'notes': 'fungal colossi: devasa mantarlar.'}, {'id': 289, 'text': 'The ground beneath them was carpeted with primitive lichens, mosses, and gigantic tree ferns.', 'translation': 'Altlarındaki zemin ilkel likenler, yosunlar ve devasa ağaç eğrelti otlarıyla halı gibi kaplanmıştı.', 'notes': 'carpeted with mosses: yosunlarla kaplanmış.'}, {'id': 290, 'text': 'All of these plants lacked vibrant colors, exhibiting only pale shades of ghostly white, brown, and yellow.', 'translation': 'Bu bitkilerin tamamı canlı renklerden yoksundu; yalnızca hayaletsi beyaz, kahverengi ve sarının soluk tonlarını sergiliyordu.', 'notes': 'lacked vibrant colors: canlı renklerden yoksundu.'}, {'id': 291, 'text': 'Without the direct golden light of the sun, nature had deprived them of true emerald chlorophyll.', 'translation': 'Güneşin doğrudan altın ışığı olmadan doğa onları gerçek zümrüt klorofilinden mahrum bırakmıştı.', 'notes': 'deprived of chlorophyll: klorofilden mahrum bırakılmış.'}, {'id': 292, 'text': 'Further along the shore, we stumbled upon an immense graveyard of petrified wooden trunks.', 'translation': 'Sahil boyunca biraz daha ileride, taşlaşmış ağaç gövdelerinden oluşan devasa bir mezarlığa rastladık.', 'notes': 'graveyard of trunks: gövdeler mezarlığı.'}, {'id': 293, 'text': 'Entire forests of ancient conifers had been turned to solid flint by mineral-rich subterranean waters.', 'translation': 'Kadim kozalaklı ağaçlardan oluşan koca ormanlar, mineral zengini yeraltı suları tarafından sert çakmaktaşına dönüştürülmüştü.', 'notes': 'turned to solid flint: sert çakmaktaşına dönüştü.'}, {'id': 294, 'text': 'Lying among the stony logs were gigantic bones bleached white by time and mineral deposits.', 'translation': 'Taşlaşmış tomrukların arasında zamanın ve mineral tortularının beyaza çevirdiği devasa kemikler yatıyordu.', 'notes': 'bleached white by time: zamanla bembeyaz olmuş.'}, {'id': 295, 'text': '"Axel, look here!" my uncle exclaimed, kneeling beside a massive jawbone armed with pointed teeth.', 'translation': 'Sivri dişlerle donatılmış devasa bir çene kemiğinin yanına diz çökerek amcam, "Axel, buraya bak!" diye seslendi.', 'notes': 'armed with pointed teeth: sivri dişlerle donanmış.'}, {'id': 296, 'text': '"This belonged to a mastodon, the colossal ancestor of the modern elephant!"', 'translation': '"Bu, modern filin devasa atası olan bir mastodona aitti!"', 'notes': 'colossal ancestor: devasa ata.'}, {'id': 297, 'text': 'I stared at the colossal skeleton in terror, wondering if any of these prehistoric monsters still lived.', 'translation': 'Bu tarih öncesi canavarlardan herhangi birinin hala yaşayıp yaşamadığını merak ederek dehşet içinde dev iskelete baktım.', 'notes': 'prehistoric monsters: tarih öncesi canavarlar.'}, {'id': 298, 'text': 'The warm breeze blowing from the sea whispered ominously through the fungal canopy.', 'translation': 'Denizden esen ılık esinti mantar çatısının arasından uğursuzca fısıldıyordu.', 'notes': 'whispered ominously: uğursuzca fısıldadı.'}, {'id': 299, 'text': 'Everything around us belonged to an epoch long erased from the surface of the globe.', 'translation': 'Çevremizdeki her şey, yerkürenin yüzeyinden çoktan silinmiş bir çağa aitti.', 'notes': 'erased from the surface: yüzeyden silinmiş.'}, {'id': 300, 'text': 'We were intruders in a forgotten world where time had frozen for millions of years.', 'translation': 'Zamanın milyonlarca yıl boyunca donup kaldığı unutulmuş bir dünyada davetsiz misafirlerdik.', 'notes': 'intruders in a forgotten world: unutulmuş bir dünyada davetsiz misafirler.'}]}, {'page_no': 16, 'title': 'Constructing the Raft and Setting Sail', 'tr_title': 'Bir Sal İnşa Edilmesi ve Yeraltı Denizine Yelken Açış', 'vocab_focus': [('raft', 'sal'), ('construction', 'inşaat, yapım'), ('timber', 'kereste, kütük'), ('buoyancy', 'suda batmama yeteneği, kaldırma kuvveti'), ('voyage', 'deniz yolculuğu'), ('embark', 'gemiye binmek, yola çıkmak'), ('provision', 'erzak, azık'), ('rudder', 'dümen')], 'sentences': [{'id': 301, 'text': 'Professor Lidenbrock was determined to cross the subterranean sea rather than wander along its rocky shoreline.', 'translation': 'Profesör Lidenbrock, kayalık kıyı şeridi boyunca dolanmaktansa yeraltı denizini aşmaya kararlıydı.', 'notes': 'determined to cross: aşmaya kararlı.'}, {'id': 302, 'text': '"Saknussemm went across, and so shall we," he declared firmly when I voiced my customary objections.', 'translation': 'Alışılagelmiş itirazlarımı dile getirdiğimde kararlılıkla, "Saknussemm karşıya geçti, biz de geçeceğiz," diye ilan etti.', 'notes': 'voiced objections: itirazlarını dile getirdi.'}, {'id': 303, 'text': 'Our resourceful guide Hans immediately set to work solving the logistical problem.', 'translation': 'Becerikli rehberimiz Hans lojistik sorunu çözmek için hemen işe koyuldu.', 'notes': 'resourceful guide: becerikli rehber.'}, {'id': 304, 'text': 'He selected logs of petrified surturbrand wood that were light yet remarkably tough.', 'translation': 'Hafif ama son derece dayanıklı olan taşlaşmış surturbrand odunundan kütükler seçti.', 'notes': 'remarkably tough: son derece sert / dayanıklı.'}, {'id': 305, 'text': 'Using our strong ropes, Hans lashed the sturdy timbers together into a compact raft ten feet wide.', 'translation': 'Güçlü urganlarımızı kullanan Hans, sağlam keresteleri on fit genişliğinde kompakt bir sal oluşturacak şekilde birbirine bağladı.', 'notes': 'lashed timbers together: keresteleri birbirine bağladı.'}, {'id': 306, 'text': 'He fashioned a solid mast from a straight fir trunk and attached a square sail made of heavy linen.', 'translation': 'Düz bir göknar gövdesinden sağlam bir direk yaptı ve kalın ketenden yapılmış kare bir yelken taktı.', 'notes': 'fashioned a solid mast: sağlam bir direk yaptı.'}, {'id': 307, 'text': 'A long flat oar mounted at the stern served as a makeshift rudder to steer our crude vessel.', 'translation': 'Kıç tarafa monte edilen uzun düz bir kürek, ilkel teknemizi yönlendirmek için derme çatma bir dümen görevi gördü.', 'notes': 'makeshift rudder: derme çatma dümen.'}, {'id': 308, 'text': 'On the morning of the thirteenth of August, the raft was launched successfully into the gentle surf.', 'translation': '13 Ağustos sabahında sal sakin dalgaların içine başarıyla indirildi.', 'notes': 'launched successfully: başarıyla suya indirildi.'}, {'id': 309, 'text': 'To our immense relief, the wood floated buoyant and high upon the dense, saline water.', 'translation': 'İçimizi çok rahatlatacak şekilde ahşap, yoğun ve tuzlu suyun üzerinde batmadan yüksekte yüzdü.', 'notes': 'floated buoyant: batmadan su üstünde yüzdü.'}, {'id': 310, 'text': 'We loaded our scientific apparatus, firearms, blankets, and remaining provisions onto the center of the raft.', 'translation': 'Bilimsel aletlerimizi, ateşli silahlarımızı, battaniyelerimizi ve kalan erzakımızı salın ortasına yükledik.', 'notes': 'remaining provisions: kalan erzak.'}, {'id': 311, 'text': 'Hans secured every trunk and flask with strong cords so nothing would be swept away by unexpected waves.', 'translation': 'Hans her sandığı ve matarayı güçlü iplerle bağladı, böylece hiçbir şey beklenmedik dalgalarla sürüklenip gitmeyecekti.', 'notes': 'swept away by waves: dalgalarla sürüklenip gitti.'}, {'id': 312, 'text': "At six o'clock, we untied our mooring lines and pushed off from the beach of Port Graüben.", 'translation': "Saat altıda bağlama iplerimizi çözdük ve Graüben Limanı'nın kumsalından denize açıldık.", 'notes': 'untied mooring lines: palamar iplerini çözdü.'}, {'id': 313, 'text': 'A fresh northern breeze caught our linen sail, filling it smoothly and propelling us southward.', 'translation': 'Taze bir kuzey esintisi keten yelkenimizi yakaladı, pürüzsüzce şişirdi ve bizi güneye doğru sevk etti.', 'notes': 'propelling us southward: bizi güneye doğru sevk etti.'}, {'id': 314, 'text': 'The shore receded rapidly, until the giant mushrooms shrank into mere dots and vanished entirely.', 'translation': 'Kıyı hızla geride kaldı; ta ki dev mantarlar küçülüp birer noktaya dönüşene ve tamamen yok olana dek.', 'notes': 'shore receded rapidly: kıyı hızla uzaklaştı / geriledi.'}, {'id': 315, 'text': 'We were sailing on an uncharted sea beneath thousands of feet of solid crust, surrounded by luminous mist.', 'translation': 'Işık saçan sisle çevrili, binlerce fitlik sert yer kabuğunun altında haritası çıkarılmamış bir denizde yelken açıyorduk.', 'notes': 'uncharted sea: haritası çıkarılmamış deniz.'}, {'id': 316, 'text': 'The raft moved at a steady speed of three and a half knots, cutting smoothly through the dark water.', 'translation': 'Sal, karanlık suyu pürüzsüzce yararak üç buçuk knotluk düzenli bir hızla ilerliyordu.', 'notes': 'cutting smoothly through: pürüzsüzce yararak geçen.'}, {'id': 317, 'text': 'Hans stood at the stern holding the rudder, motionless and vigilant as always.', 'translation': 'Hans kıçta dümeni tutarak her zamanki gibi hareketsiz ve tetikte duruyordu.', 'notes': 'motionless and vigilant: hareketsiz ve uyanık / tetikte.'}, {'id': 318, 'text': 'My uncle calculated our navigation coordinates in his pocket notebook with relentless mathematical precision.', 'translation': 'Amcam cep not defterinde seyrüsefer koordinatlarımızı amansız bir matematiksel hassasiyetle hesapladı.', 'notes': 'relentless mathematical precision: amansız matematiksel kesinlik.'}, {'id': 319, 'text': 'I leaned over the side, watching the crystal-clear water where no bottom could be seen.', 'translation': 'Hiçbir tabanın görülemediği berrak suya bakarak teknenin kenarından aşağıya eğildim.', 'notes': 'leaned over the side: kenarından aşağı eğildi.'}, {'id': 320, 'text': 'What unimaginable monsters were lurking in the mysterious depths beneath our fragile wooden craft?', 'translation': 'Kırılgan ahşap teknemizin altındaki gizemli derinliklerde hangi akıl almaz canavarlar pusuya yatmıştı?', 'notes': 'lurking in the depths: derinliklerde pusuya yatan.'}]}, {'page_no': 17, 'title': 'Primeval Fish and Signs of Sea Monsters', 'tr_title': 'Oltaya Gelen İlkel Balıklar ve Devasa Deniz Sürüngenleri', 'vocab_focus': [('eyeless', 'gözsüz, gözleri körelmiş'), ('specimen', 'örnek, numune'), ('extinct', 'soyu tükenmiş'), ('sounding', 'iskandil, derinlik ölçümü'), ('abyss', 'uçurum, derin boşluk'), ('reptile', 'sürüngen'), ('carnivorous', 'etçil'), ('fathom', 'kulaç (deniz derinlik ölçüsü)')], 'sentences': [{'id': 321, 'text': 'On the fourteenth of August, Hans baited a strong iron hook with raw meat and threw the line into the sea.', 'translation': "14 Ağustos'ta Hans güçlü bir demir kancaya çiğ et taktı ve oltayı denize fırlattı.", 'notes': 'baited a strong hook: güçlü kancaya yem taktı.'}, {'id': 322, 'text': 'Within two hours, the line jerked violently, almost pulling the guide into the deep water.', 'translation': 'İki saat içinde misina şiddetle sarsıldı, neredeyse rehberi derin suların içine çekecekti.', 'notes': 'jerked violently: şiddetle sarsıldı.'}, {'id': 323, 'text': 'With his mighty arms, Hans hauled a thrashing creature onto the wooden deck of the raft.', 'translation': 'Kuvvetli kollarıyla Hans, çırpınan bir yaratığı salın ahşap güvertesine çekti.', 'notes': 'thrashing creature: çırpınan yaratık.'}, {'id': 324, 'text': 'It was a strange fish with a flat, armored head and a body covered with hard, diamond-shaped scales.', 'translation': 'Yassı zırhlı bir başı ve sert, elmas biçimli pullarla kaplı gövdesi olan garip bir balıktı bu.', 'notes': 'diamond-shaped scales: elmas biçimli pullar.'}, {'id': 325, 'text': '"Look at this creature!" my uncle exclaimed, kneeling down to inspect it with intense fascination.', 'translation': 'Yoğun bir hayranlıkla incelemek için diz çökerek amcam, "Şu yaratığa bak!" diye haykırdı.', 'notes': 'intense fascination: yoğun hayranlık / büyülenme.'}, {'id': 326, 'text': '"It is a sturgeon belonging to an extinct genus that disappeared from the Earth during the Devonian epoch!"', 'translation': '"Devoniyen çağında yeryüzünden silinmiş, soyu tükenmiş bir cinse ait bir mersin balığı bu!"', 'notes': 'extinct genus: soyu tükenmiş cins.'}, {'id': 327, 'text': 'Most remarkable of all, this primitive creature possessed no eyes whatsoever.', 'translation': 'Her şeyden daha da dikkat çekici olanı, bu ilkel yaratığın kesinlikle hiçbir gözü yoktu.', 'notes': 'no eyes whatsoever: kesinlikle hiçbir gözü yok.'}, {'id': 328, 'text': 'Generations of living in eternal darkness had rendered optical organs completely useless and obsolete.', 'translation': 'Ebedi karanlıkta geçen nesiller, görme organlarını tamamen yararsız ve körelmiş hale getirmişti.', 'notes': 'useless and obsolete: yararsız ve körelmiş.'}, {'id': 329, 'text': 'Hans cleaned the strange catch and cooked it over our burner, offering us a delicious and nourishing meal.', 'translation': 'Hans bu garip avı temizledi ve ocağımızda pişirerek bize lezzetli ve besleyici bir yemek sundu.', 'notes': 'nourishing meal: besleyici öğün.'}, {'id': 330, 'text': 'That afternoon, my uncle decided to take soundings to determine the depth of the subterranean basin.', 'translation': 'O öğleden sonra amcam, yeraltı havzasının derinliğini belirlemek için iskandil almaya karar verdi.', 'notes': 'take soundings: iskandil almak / derinlik ölçmek.'}, {'id': 331, 'text': 'He tied a heavy iron crowbar to a coil of rope two hundred fathoms long and threw it overboard.', 'translation': 'Ağır bir demir levyeyi iki yüz kulaç uzunluğundaki bir halat kangalına bağladı ve bordadan aşağı attı.', 'notes': 'iron crowbar: demir levye.'}, {'id': 332, 'text': 'The rope paid out rapidly through his fingers until the entire two hundred fathoms were exhausted without touching bottom.', 'translation': 'İki yüz kulacın tamamı tabana değmeden tükenene kadar halat hızla parmaklarının arasından kayıp gitti.', 'notes': 'rope paid out: halat salındı / boşaldı.'}, {'id': 333, 'text': '"The sea is bottomless!" cried the professor, staring into the dark water with astonished eyes.', 'translation': 'Şaşkın gözlerle karanlık suya bakarak profesör, "Deniz dipsiz!" diye bağırdı.', 'notes': 'staring into dark water: karanlık suya bakarak.'}, {'id': 334, 'text': 'When we pulled the line back onto the raft, Hans noticed deep tooth marks on the thick iron bar.', 'translation': 'İpi sala geri çektiğimizde, Hans kalın demir çubuğun üzerindeki derin diş izlerini fark etti.', 'notes': 'deep tooth marks: derin diş izleri.'}, {'id': 335, 'text': 'The metal had been twisted and gouged by enormous jaws possessing terrifying, superhuman crushing power.', 'translation': 'Metal, korkunç ve insanüstü bir ezme gücüne sahip devasa çeneler tarafından bükülmüş ve oyulmuştu.', 'notes': 'crushing power: ezici güç.'}, {'id': 336, 'text': '"What kind of monster could bite into solid iron?" I stammered, feeling cold terror clutch my heart.', 'translation': 'Soğuk bir dehşetin kalbimi pençelediğini hissederek, "Nasıl bir canavar sert demiri ısırabilir?" diye kekeledim.', 'notes': 'cold terror clutch heart: soğuk dehşet kalbi pençeledi.'}, {'id': 337, 'text': '"A creature compared to which the great whale of our oceans is a mere dwarf," whispered my uncle.', 'translation': 'Amcam, "Okyanuslarımızın büyük balinasının yanında cüce kalacağı türden bir yaratık," diye fısıldadı.', 'notes': 'a mere dwarf: sadece bir cüce.'}, {'id': 338, 'text': 'He checked his double-barreled rifle, loading both chambers with explosive bullets.', 'translation': 'Her iki namluyu da patlayıcı kurşunlarla doldurarak çifte namlulu tüfeğini kontrol etti.', 'notes': 'double-barreled rifle: çifte namlulu tüfek.'}, {'id': 339, 'text': 'A heavy silence descended over the raft, broken only by the whistling wind and our anxious breathing.', 'translation': 'Yalnızca ıslık çalan rüzgar ve endişeli nefeslerimizle bozulan ağır bir sessizlik salın üzerine çöktü.', 'notes': 'heavy silence descended: ağır bir sessizlik çöktü.'}, {'id': 340, 'text': 'We knew that somewhere beneath our timber planks, the terrifying monarchs of the Jurassic ocean were hunting.', 'translation': 'Ahşap kalaslarımızın altında bir yerlerde Jura okyanusunun korkunç hükümdarlarının avlandığını biliyorduk.', 'notes': 'terrifying monarchs: korkunç hükümdarlar.'}]}, {'page_no': 18, 'title': 'The Duel of the Prehistoric Leviathans', 'tr_title': "İhtiyozor ve Pleziyozor'un Sal Yanındaki Korkunç Savaşı", 'vocab_focus': [('ichthyosaurus', 'ihtiyozor (balık kertenkelesi)'), ('plesiosaurus', 'pleziyozor (uzun boyunlu deniz sürüngeni)'), ('leviathan', 'deniz canavarı, dev yaratık'), ('serpentine', 'yılansı, kıvrımlı'), ('combat', 'muharebe, ölümcül dövüş'), ('agony', 'can çekişme, şiddetli acı'), ('submerge', 'suya batmak, dalmak'), ('monstrous', 'devasa, korkunç')], 'sentences': [{'id': 341, 'text': 'On the morning of the eighteenth of August, the water suddenly bubbled and heaved around our raft.', 'translation': '18 Ağustos sabahında su, salımızın etrafında aniden kaynadı ve kabardı.', 'notes': 'bubbled and heaved: köpürüp kabardı.'}, {'id': 342, 'text': 'Hans pointed toward the horizon where an enormous black mass rose above the surface.', 'translation': 'Hans, yüzeyin üzerinde devasa siyah bir kütlenin yükseldiği ufka doğru işaret etti.', 'notes': 'enormous black mass: devasa siyah kütle.'}, {'id': 343, 'text': '"It is a colossal porpoise!" I shouted, but a moment later another monstrous form breached the waves.', 'translation': '"O devasa bir yunus!" diye bağırdım ama bir an sonra bir başka canavarca biçim dalgaları yardı.', 'notes': 'breached the waves: dalgaları yarıp yüzeye çıktı.'}, {'id': 344, 'text': '"No!" cried my uncle. "There is a sea crocodile with the teeth of a shark, and beside it a giant turtle!"', 'translation': 'Amcam, "Hayır!" diye haykırdı. "Orada köpekbalığı dişlerine sahip bir deniz timsahı var ve yanında da dev bir kaplumbağa!"', 'notes': 'sea crocodile: deniz timsahı.'}, {'id': 345, 'text': 'Two antediluvian leviathans were approaching each other, their movements churning the calm water into white foam.', 'translation': 'Tufan öncesi iki deniz canavarı birbirine yaklaşıyordu ve hareketleri sakin suyu beyaz köpüğe çeviriyordu.', 'notes': 'antediluvian leviathans: tufan öncesi dev deniz yaratıkları.'}, {'id': 346, 'text': 'The first monster was an Ichthyosaurus, over one hundred feet in length, with the snout of a porpoise and gigantic circular eyes.', 'translation': "İlk canavar, yüz fitten uzun boyu, yunus burnu ve devasa yuvarlak gözleriyle bir İhtiyozor'du.", 'notes': 'gigantic circular eyes: devasa yuvarlak gözler.'}, {'id': 347, 'text': 'Its eyes were as large as carriage wheels, glowing with terrifying ferocity in the electrical luminescence.', 'translation': 'Gözleri fayton tekerlekleri kadar büyüktü ve elektriksel ışıltı içinde korkunç bir vahşetle parlıyordu.', 'notes': 'carriage wheels: fayton tekerlekleri.'}, {'id': 348, 'text': 'The second creature was a Plesiosaurus, a gigantic serpent with a cylindrical body, a short tail, and paddles like oars.', 'translation': "İkinci yaratık ise silindirik bir gövdesi, kısa bir kuyruğu ve kürek benzeri yüzgeçleri olan devasa bir yılan gibi bir Pleziyozor'du.", 'notes': 'serpent with cylindrical body: silindirik gövdeli yılan.'}, {'id': 349, 'text': 'Its long, flexible neck rose thirty feet out of the sea, darting like an enormous swan striking at prey.', 'translation': 'Uzun ve esnek boynu denizden otuz fit dışarı yükseliyor, ava vuran devasa bir kuğu gibi ileri atılıyordu.', 'notes': 'darting like a swan: kuğu gibi ileri atılan.'}, {'id': 350, 'text': 'The two prehistoric titans collided with the fury of thunderbolts, completely ignoring our trembling raft.', 'translation': 'İki tarih öncesi titan, titreyen salımızı tamamen görmezden gelerek yıldırım öfkesiyle çarpıştı.', 'notes': 'collided with the fury: öfkeyle çarpıştı.'}, {'id': 351, 'text': 'The Plesiosaurus wound its serpentine coils around the armored flank of the Ichthyosaurus.', 'translation': "Pleziyozor yılansı kıvrımlarını İhtiyozor'un zırhlı böğrüne doladı.", 'notes': 'serpentine coils: yılansı kıvrımlar / halkalar.'}, {'id': 352, 'text': "In response, the giant fish sank its rows of conical teeth into the reptile's soft, writhing neck.", 'translation': 'Buna karşılık dev balık, konik diş sıralarını sürüngenin yumuşak, kıvranan boynuna geçirdi.', 'notes': 'rows of conical teeth: konik diş sıraları.'}, {'id': 353, 'text': 'Fountains of red blood erupted into the air, staining the surface of the subterranean sea for miles around.', 'translation': 'Kızıl kan fıskiyeleri havaya püskürdü ve yeraltı denizinin yüzeyini miller boyunca kızıla boyadı.', 'notes': 'fountains of red blood: kızıl kan fıskiyeleri.'}, {'id': 354, 'text': 'The violent battle created immense tidal waves that threatened to overturn our fragile craft at every surge.', 'translation': 'Şiddetli muharebe, her kabarmada kırılgan teknemizi alabora etmekle tehdit eden devasa dalgalar yarattı.', 'notes': 'threatened to overturn: alabora etmekle tehdit etti.'}, {'id': 355, 'text': 'Hans clung tightly to the rudder, keeping the raft aligned with the crashing breakers with superhuman composure.', 'translation': 'Hans dümeni sımsıkı tuttu ve insanüstü bir soğukkanlılıkla salı çarpan dalgaların doğrultusunda tuttu.', 'notes': 'superhuman composure: insanüstü soğukkanlılık.'}, {'id': 356, 'text': 'For two agonizing hours, the primeval duel raged between the snapping jaws and twisting coils.', 'translation': 'İki ıstırap dolu saat boyunca şakırdayan çeneler ile kıvrılan halkalar arasında ilkel düello sürüp gitti.', 'notes': 'primeval duel raged: ilkel düello şiddetle sürdü.'}, {'id': 357, 'text': 'At last, the thrashing of the Plesiosaurus grew weak as its severed throat poured life onto the waves.', 'translation': "Sonunda, parçalanan boğazı dalgaların üzerine hayat akıtırken Pleziyozor'un çırpınışları zayıfladı.", 'notes': 'severed throat: parçalanmış / kesilmiş boğaz.'}, {'id': 358, 'text': 'The dying serpent collapsed into the sea, its lifeless neck trailing behind in the bloody foam.', 'translation': 'Can çekişen yılan, cansız boynu kanlı köpüğün ardında sürüklenerek denize yığıldı.', 'notes': 'collapsed into the sea: denize yığıldı.'}, {'id': 359, 'text': 'The victorious Ichthyosaurus plunged into the unfathomable depths to devour its slaughtered adversary.', 'translation': 'Zafer kazanan İhtiyozor, katledilen hasmını yutmak için dipsiz derinliklere daldı.', 'notes': 'slaughtered adversary: katledilen hasım / rakip.'}, {'id': 360, 'text': 'We exhaled a collective sigh of deliverance, knowing we had narrowly escaped the most horrific demise.', 'translation': 'En korkunç ölümden kıl payı kurtulduğumuzu bilerek hep birlikte bir kurtuluş nefesi verdik.', 'notes': 'collective sigh of deliverance: hep birlikte verilen kurtuluş nefesi.'}]}, {'page_no': 19, 'title': 'The Tempest and Shipwreck in the Subterranean Sea', 'tr_title': 'Korkunç Yeraltı Fırtınası ve Salın Kayalıklara Çarpması', 'vocab_focus': [('tempest', 'şiddetli fırtına, boran'), ('hurricane', 'kasırga'), ('lightning', 'şimşek, yıldırım'), ('electric', 'elektrikli, elektrik yüklü'), ('shipwreck', 'gemi kazası, batık'), ('survivor', 'hayatta kalan'), ('fury', 'öfke, hiddet'), ('strife', 'mücadele, çatışma')], 'sentences': [{'id': 361, 'text': 'On the twenty-sixth of August, the air grew oppressively hot and charged with heavy atmospheric electricity.', 'translation': "26 Ağustos'ta hava boğucu derecede ısındı ve yoğun atmosferik elektrikle yüklendi.", 'notes': 'oppressively hot: boğucu derecede sıcak.'}, {'id': 362, 'text': 'Our hair stood on end, and small blue sparks leaped from our fingertips whenever we touched metal objects.', 'translation': 'Saçlarımız dikildi ve metal nesnelere ne zaman dokunsak parmak uçlarımızdan küçük mavi kıvılcımlar sıçradı.', 'notes': 'hair stood on end: saçları diken diken oldu.'}, {'id': 363, 'text': 'Dense, pitch-black clouds gathered rapidly beneath the towering granite ceiling of the cavern.', 'translation': 'Mağaranın yükselen granit tavanının altında hızla yoğun, zifiri karanlık bulutlar toplandı.', 'notes': 'pitch-black clouds: zifiri siyah bulutlar.'}, {'id': 364, 'text': '"A subterranean hurricane is upon us!" shouted my uncle, struggling to secure the loose luggage.', 'translation': 'Gevşek bagajları bağlamaya çabalayan amcam, "Bir yeraltı kasırgası üzerimize geliyor!" diye bağırdı.', 'notes': 'hurricane is upon us: kasırga başımızda / üzerimize geliyor.'}, {'id': 365, 'text': 'Before we could lower the linen sail, a furious squall struck our raft with devastating violence.', 'translation': 'Biz keten yelkeni indiremeden, azgın bir boran yıkıcı bir şiddetle salımıza çarptı.', 'notes': 'furious squall struck: azgın boran çarptı.'}, {'id': 366, 'text': 'The mast snapped like a fragile reed, and our sail was ripped away into the whirling black sky.', 'translation': 'Direk kırılgan bir kamış gibi kırıldı ve yelkenimiz girdaplı siyah gökyüzüne doğru kopup gitti.', 'notes': 'snapped like a fragile reed: narin bir kamış gibi kırıldı.'}, {'id': 367, 'text': 'Colossal waves, thirty feet high, lifted our little platform and plunged it into deep watery chasms.', 'translation': 'Otuz fit yüksekliğindeki devasa dalgalar küçük platformumuzu havaya kaldırdı ve derin sulu yarıklara fırlattı.', 'notes': 'plunged into deep chasms: derin yarıklara fırlattı.'}, {'id': 368, 'text': 'Hans tied Axel and the professor to the heavy timbers with thick cords to keep us from being washed away.', 'translation': "Hans, dalgalara kapılıp gitmeyelim diye Axel'ı ve profesörü kalın iplerle ağır kerestelere bağladı.", 'notes': 'washed away: dalgalarla sürüklenip gitmek.'}, {'id': 369, 'text': 'Thunder roared continuously through the underground vault with a deafening reverberation that shook our bones.', 'translation': 'Gök gürültüsü kemiklerimizi sarsan sağır edici bir yankılanmayla yeraltı kubbesinde aralıksız gürledi.', 'notes': 'deafening reverberation: sağır edici yankılanma.'}, {'id': 370, 'text': 'Brilliant flashes of sheet lightning illuminated the wild foam, turning the sea into a cauldron of white fire.', 'translation': 'Şimşeklerin parlak çakışları vahşi köpüğü aydınlattı, denizi beyaz bir ateş kazanına çevirdi.', 'notes': 'cauldron of white fire: beyaz ateş kazanı.'}, {'id': 371, 'text': "Suddenly, a glowing sphere of electrical plasma—a ball of Saint Elmo's fire—settled upon our shattered mast.", 'translation': 'Aniden, parıldayan bir elektriksel plazma küresi—bir Aziz Elmo ateşi topu—parçalanmış direğimizin üzerine kondu.', 'notes': "Saint Elmo's fire: Aziz Elmo ateşi."}, {'id': 372, 'text': 'The azure fireball hissed and spun with blinding brilliance, hopping from our gunpowder kegs to our iron tools.', 'translation': 'Masmavi ateş topu barut fıçılarımızdan demir aletlerimize sıçrayarak kör edici bir parlaklıkla tısladı ve döndü.', 'notes': 'blinding brilliance: kör edici parlaklık.'}, {'id': 373, 'text': 'I watched in paralyzed horror, expecting our gunpowder to explode at any microsecond and tear us to atoms.', 'translation': 'Barutumuzun her an patlayıp bizi atomlarımıza ayırmasını bekleyerek felç olmuş bir dehşet içinde izledim.', 'notes': 'paralyzed horror: felç eden dehşet.'}, {'id': 374, 'text': 'For four dreadful days and nights, the tempest drove our raft across the uncharted sea at dizzying speed.', 'translation': 'Dört korkunç gün ve gece boyunca fırtına, salımızı haritası çıkarılmamış denizde baş döndürücü bir hızla sürükledi.', 'notes': 'dizzying speed: baş döndürücü hız.'}, {'id': 375, 'text': 'We had neither food nor rest, soaked to the bone and battered by the merciless subterranean gale.', 'translation': 'İliğimize kadar ıslanmış ve acımasız yeraltı fırtınasıyla hırpalanmış halde ne yemeğimiz vardı ne de dinlenebildik.', 'notes': 'soaked to the bone: iliklerine kadar ıslanmış.'}, {'id': 376, 'text': 'On the fifth day, a terrifying sound rose above the roar of the wind: the booming of breakers on rocks.', 'translation': 'Beşinci günde rüzgarın kükremesinin üzerinde korkunç bir ses yükseldi: dalgaların kayalıklarda patlaması.', 'notes': 'breakers on rocks: kayalara çarpan azgın dalgalar.'}, {'id': 377, 'text': '"Land!" cried Hans, his voice rising in alarm for the first time since our expedition began.', 'translation': 'Keşif gezimiz başladığından beri ilk kez sesi telaşla yükselen Hans, "Kara!" diye bağırdı.', 'notes': 'rising in alarm: telaşla yükselen.'}, {'id': 378, 'text': 'Before us loomed a wall of jagged basalt reefs upon which immense waves were crashing with explosive fury.', 'translation': 'Önümüzde, devasa dalgaların patlayıcı bir öfkeyle çarptığı sarp bazalt resiflerinden bir duvar belirdi.', 'notes': 'jagged basalt reefs: sarp bazalt resifleri.'}, {'id': 379, 'text': 'A monstrous wave picked up our craft and hurled it straight into the black granite barrier.', 'translation': 'Canavarca bir dalga teknemizi kaldırdı ve dosdoğru siyah granit barikatın üzerine fırlattı.', 'notes': 'hurled it straight into: dosdoğru içine fırlattı.'}, {'id': 380, 'text': 'The raft splintered with a sickening crunch, and I was thrown violently onto a sandy ledge before blacking out.', 'translation': 'Sal insanın içini kaldıran bir çatırtıyla parçalandı ve ben bilincimi kaybetmeden önce şiddetle kumlu bir sete fırlatıldım.', 'notes': 'splintered with a crunch: çatırtıyla paramparça oldu.'}]}, {'page_no': 20, 'title': 'The Fossil Man and the Colossal Shepherd', 'tr_title': 'Tarih Öncesi İnsan Kafatası ve Mamut Sürüsünü Güden Dev Çoban', 'vocab_focus': [('cranium', 'kafatası, kafatası kemiği'), ('antediluvian', 'tufan öncesi döneme ait'), ('mammoth', 'mamut'), ('colossus', 'devasa anıt, dev varlık'), ('shepherd', 'çoban'), ('herd', 'sürü'), ('anthropological', 'antropolojik, insanbilimsel'), ('miraculous', 'mucizevi')], 'sentences': [{'id': 381, 'text': 'When I regained consciousness, I found myself resting safely on a wide shore of golden sand.', 'translation': 'Yeniden bilincime kavuştuğumda kendimi altın rengi kumdan geniş bir sahilde güvenle dinlenirken buldum.', 'notes': 'regained consciousness: bilincini yeniden kazandı.'}, {'id': 382, 'text': 'Hans had once again performed a miracle, pulling both my uncle and me from the foaming jaws of death.', 'translation': 'Hans hem amcamı hem de beni ölümün köpüren çenelerinden çekip alarak bir kez daha mucize yaratmıştı.', 'notes': 'foaming jaws of death: ölümün köpüren çeneleri.'}, {'id': 383, 'text': 'Remarkably, most of our precious apparatus, gunpowder kegs, and food packages had also been salvaged.', 'translation': 'Dikkate değer bir şekilde değerli aletlerimizin, barut fıçılarımızın ve yiyecek paketlerimizin çoğu da kurtarılmıştı.', 'notes': 'salvaged: kurtarıldı.'}, {'id': 384, 'text': 'The furious hurricane had blown itself out, leaving the subterranean sea calm and peaceful once again.', 'translation': 'Öfkeli kasırga gücünü tüketmiş, yeraltı denizini bir kez daha sakin ve huzurlu bırakmıştı.', 'notes': 'blown itself out: gücünü tüketip dinmiş.'}, {'id': 385, 'text': 'While Hans repaired the battered raft, my uncle and I set out to explore the uncharted coast.', 'translation': 'Hans hırpalanmış salı tamir ederken, amcam ve ben haritası çıkarılmamış sahili keşfetmek üzere yola çıktık.', 'notes': 'set out to explore: keşfetmek üzere yola çıktı.'}, {'id': 386, 'text': 'We soon discovered a vast plain littered with hundreds of thousands of fossilized skeletons.', 'translation': 'Kısa süre sonra yüz binlerce fosilleşmiş iskeletle dolu devasa bir ovayı keşfettik.', 'notes': 'littered with skeletons: iskeletlerle dolu / saçılmış.'}, {'id': 387, 'text': 'Here lay the petrified remains of mastodons, dinotheriums, megatheriums, and ancient pachyderms.', 'translation': 'Burada mastodonların, dinoteryumların, megateryumların ve kadim kalın derililerin taşlaşmış kalıntıları yatıyordu.', 'notes': 'petrified remains: taşlaşmış kalıntılar.'}, {'id': 388, 'text': 'Suddenly, Professor Lidenbrock uttered a loud cry and knelt beside a rounded bone half-buried in the sand.', 'translation': 'Aniden Profesör Lidenbrock yüksek bir çığlık attı ve kuma yarı gömülü yuvarlak bir kemiğin yanında diz çöktü.', 'notes': 'half-buried in sand: kuma yarı gömülü.'}, {'id': 389, 'text': 'He held up a perfectly preserved human cranium with trembling, worshipful hands.', 'translation': 'Titreyen, taparcasına elleriyle kusursuz korunmuş bir insan kafatasını havaya kaldırdı.', 'notes': 'human cranium: insan kafatası.'}, {'id': 390, 'text': '"A human skull, Axel!" he cried, tears of triumph gleaming in his spectacles.', 'translation': 'Gözlüklerinde zafer gözyaşları parıldayarak, "Bir insan kafatası, Axel!" diye haykırdı.', 'notes': 'tears of triumph: zafer gözyaşları.'}, {'id': 391, 'text': '"The skull of an antediluvian man who lived contemporaneously with the mastodon and the giant elk!"', 'translation': '"Mastodon ve dev geyikle aynı çağda yaşamış tufan öncesi bir insanın kafatası bu!"', 'notes': 'lived contemporaneously: çağdaş olarak yaşadı.'}, {'id': 392, 'text': 'This discovery shattered every established geological dogma regarding the origin and antiquity of mankind.', 'translation': 'Bu keşif, insanlığın kökeni ve kadimliği konusundaki yerleşik tüm jeolojik dogmaları yerle bir etti.', 'notes': 'shattered established dogma: yerleşik dogmaları yıktı.'}, {'id': 393, 'text': 'We advanced further into a forest of primeval arborescent ferns, drawn by a mysterious sound.', 'translation': 'Gizemli bir sesin peşinden ilkel ağaçsı eğrelti otlarından oluşan bir ormanın daha da içine ilerledik.', 'notes': 'arborescent ferns: ağaçsı eğrelti otları.'}, {'id': 394, 'text': 'Through an opening in the trees, we beheld a sight that froze the blood in our veins.', 'translation': 'Ağaçların arasındaki bir açıklıktan damarlarımızdaki kanı donduran bir manzaraya şahit olduk.', 'notes': 'froze the blood in veins: damarlarındaki kanı dondurdu.'}, {'id': 395, 'text': 'A herd of gigantic living mammoths was grazing peacefully on the subterranean foliage.', 'translation': 'Canlı devasa mamutlardan oluşan bir sürü yeraltı yapraklarını huzur içinde otluyordu.', 'notes': 'grazing peacefully: huzurla otlayan.'}, {'id': 396, 'text': 'Their enormous curved tusks gleamed in the twilight, and their massive hairy trunks uprooted entire bushes.', 'translation': 'Devasa kıvrık fildişleri alacakaranlıkta parıldıyor ve dev kıllı hortumları koca çalıları kökünden söküyordu.', 'notes': 'enormous curved tusks: devasa kıvrık fildişleri.'}, {'id': 397, 'text': 'Even more incredible, leaning against a gigantic trunk was a living colossus over twelve feet tall!', 'translation': 'Daha da inanılmazı, devasa bir gövdeye yaslanmış halde boyu on iki fiti aşan canlı bir dev vardı!', 'notes': 'living colossus: canlı bir dev / devasa varlık.'}, {'id': 398, 'text': 'It was a giant shepherd with wild mane of hair, guiding the herd of primeval beasts with a huge club.', 'translation': 'Yabanıl yele gibi saçları olan, devasa bir sopayla ilkel canavarlar sürüsünü güden dev bir çobandı bu.', 'notes': 'giant shepherd: dev çoban.'}, {'id': 399, 'text': '"Flee, Uncle!" I whispered in mortal terror, pulling him backward before the giant could spot us.', 'translation': 'Dev bizi fark etmeden önce amcamı geriye doğru çekerek ölümcül bir dehşetle, "Kaçalım amca!" diye fısıldadım.', 'notes': 'mortal terror: ölümcül dehşet.'}, {'id': 400, 'text': 'We retreated in breathless haste back toward the safety of the rocky shore where Hans was waiting.', 'translation': "Hans'ın beklediği kayalık sahilin güvenliğine doğru nefes nefese bir telaşla geri çekildik.", 'notes': 'retreated in breathless haste: nefes nefese bir aceleyle geri çekildi.'}]}, {'page_no': 21, 'title': "Saknussemm's Runes and the Blocked Portal", 'tr_title': "Saknussemm'in Baş Harflerinin Kazındığı Tıkalı Kaya Geçidi", 'vocab_focus': [('initials', 'baş harfler'), ('monolithic', 'monolitik, yekpare taştan'), ('obstruction', 'engel, tıkanıklık'), ('impassable', 'geçilmez, geçit vermez'), ('granite', 'granit'), ('runic', 'rünik, rün yazısına ait'), ('galvanize', 'harekete geçirmek, canlandırmak'), ('portal', 'büyük kapı, geçit')], 'sentences': [{'id': 401, 'text': 'Having escaped the primeval forest, we walked along the base of towering cliffs of dark granite.', 'translation': 'İlkel ormandan kaçtıktan sonra koyu granitten yükselen uçurumların eteği boyunca yürüdük.', 'notes': 'base of towering cliffs: yükselen sarp kayalıkların eteği.'}, {'id': 402, 'text': 'My uncle took out his pocket compass to determine our direction across this new continent.', 'translation': 'Amcam bu yeni kıtadaki yönümüzü belirlemek için cep pusulasını çıkardı.', 'notes': 'determine our direction: yönümüzü belirlemek.'}, {'id': 403, 'text': 'To his utter bewilderment, the needle pointed north toward the sea we had just crossed.', 'translation': 'Onu tam bir hayrete düşürecek şekilde ibre, az önce geçtiğimiz denize doğru, yani kuzeye işaret ediyordu.', 'notes': 'utter bewilderment: tam bir şaşkınlık / hayret.'}, {'id': 404, 'text': 'The tempest had reversed its fury and blown our raft entirely backward to the northern shore!', 'translation': 'Fırtına öfkesini tersine çevirmiş ve salımızı tamamen geriye, kuzey kıyısına savurmuştu!', 'notes': 'blown raft backward: salı geriye doğru savurdu.'}, {'id': 405, 'text': 'Professor Lidenbrock fell into a paroxysm of uncontrollable rage, kicking the sand in futile anger.', 'translation': 'Profesör Lidenbrock nafile bir öfkeyle kumu tekmeleyerek kontrolsüz bir hiddet krizine tutuldu.', 'notes': 'paroxysm of rage: öfke krizi / nöbeti.'}, {'id': 406, 'text': 'All our perilous maritime journey seemed to have brought us right back to our starting point.', 'translation': 'Tüm o tehlikeli deniz yolculuğumuz bizi sanki dosdoğru başlangıç noktamıza geri getirmiş gibiydi.', 'notes': 'perilous maritime journey: tehlikeli deniz yolculuğu.'}, {'id': 407, 'text': 'However, as I wandered along the rocky wall, my foot struck something hard half-buried in the shingle.', 'translation': 'Ancak kayalık duvar boyunca gezinirken ayağım çakılların içine yarı gömülü sert bir şeye çarptı.', 'notes': 'half-buried in shingle: çakılların arasına yarı gömülü.'}, {'id': 408, 'text': 'It was a rusty sixteenth-century dagger, carved with Spanish craftsmanship.', 'translation': 'İspanyol işçiliğiyle oyulmuş, paslı bir on altıncı yüzyıl hançeriydi bu.', 'notes': 'rusty dagger: paslı hançer.'}, {'id': 409, 'text': '"Uncle, look what I have found!" I cried, holding the ancient blade aloft in the electrical light.', 'translation': 'Kadim kılıcı elektrik ışığında havaya kaldırarak, "Amca, ne bulduğuma bak!" diye bağırdım.', 'notes': 'holding blade aloft: bıçağı havaya kaldırarak.'}, {'id': 410, 'text': '"A dagger!" he gasped. "A weapon left behind by human hands hundreds of years ago!"', 'translation': 'Nefesi kesilerek, "Bir hançer!" dedi. "Yüzlerce yıl önce insan elleri tarafından geride bırakılmış bir silah!"', 'notes': 'left behind by human hands: insan elleriyle geride bırakılmış.'}, {'id': 411, 'text': 'Saknussemm must have stood upon this exact spot before engraving his next signpost.', 'translation': 'Saknussemm bir sonraki işaretini kazımadan önce tam da bu noktada durmuş olmalıydı.', 'notes': 'engraving next signpost: sonraki yol işaretini kazımak.'}, {'id': 412, 'text': 'We scrutinized the dark cliff face with our magnifying lenses, examining every fissure and crevice.', 'translation': 'Her yarığı ve çatlağı inceleyerek koyu renk uçurum yüzeyini büyüteçlerimizle dikkatle taradık.', 'notes': 'scrutinized cliff face: uçurum yüzünü titizlikle inceledi.'}, {'id': 413, 'text': 'A few yards further, near the entrance of a dark opening, my uncle gave a cry of triumphant joy.', 'translation': 'Birkaç yarda ileride, karanlık bir açıklığın girişinin yakınında amcam zafer dolu bir sevinç çığlığı attı.', 'notes': 'cry of triumphant joy: zafer dolu sevinç çığlığı.'}, {'id': 414, 'text': "Carved into the vertical granite were two ancient runic characters: 'A. S.'", 'translation': "Dikey granitin içine kazınmış iki kadim rün harfi vardı: 'A. S.'", 'notes': 'carved into vertical granite: dikey granitin içine oyulmuş.'}, {'id': 415, 'text': '"Arne Saknussemm! Always Saknussemm!" the professor shouted, kissing the cold stone with reverence.', 'translation': 'Profesör soğuk taşı hürmetle öperek, "Arne Saknussemm! Her zaman Saknussemm!" diye haykırdı.', 'notes': 'kissing with reverence: hürmetle öperek.'}, {'id': 416, 'text': 'This was the true continuation of the route to the center of the Earth, leading through this dark passage.', 'translation': "Bu, Dünya'nın merkezine giden rotanın bu karanlık geçitten geçen gerçek devamıydı.", 'notes': 'continuation of the route: rotanın devamı.'}, {'id': 417, 'text': 'We rushed into the gallery, eager to pursue our glorious descent beneath the continent.', 'translation': 'Kıtanın altındaki o şanlı inişimize devam etmek için can atarak galeriye doğru koştuk.', 'notes': 'eager to pursue: sürdürmeye hevesli.'}, {'id': 418, 'text': 'However, after taking barely twenty paces, our progress was abruptly halted by a catastrophic obstruction.', 'translation': 'Ne var ki ancak yirmi adım attıktan sonra ilerleyişimiz feci bir engelle aniden durdu.', 'notes': 'abruptly halted: aniden durduruldu.'}, {'id': 419, 'text': 'An enormous monolithic boulder of granite had fallen from the ceiling, completely sealing the tunnel mouth.', 'translation': 'Tavandan düşen devasa, yekpare bir granit kaya kütlesi tünelin ağzını tamamen kapatmıştı.', 'notes': 'completely sealing the mouth: ağzını tamamen mühürleyen / kapatan.'}, {'id': 420, 'text': 'It was an impassable wall of impenetrable rock, barring our way into the depths of the planet.', 'translation': 'Gezegenin derinliklerine giden yolumuzu tıkayan, geçit vermez taştan aşılmaz bir duvardı bu.', 'notes': 'impassable wall: geçit vermez / aşılmaz duvar.'}]}, {'page_no': 22, 'title': 'Blasting the Granite Gate with Gunpowder', 'tr_title': 'Geçidi Açmak İçin Barutla Patlatma Yapılması', 'vocab_focus': [('gunpowder', 'kara barut'), ('detonation', 'patlama, infilak'), ('cartridge', 'kartuş, fişek'), ('fuse', 'fitil'), ('demolition', 'yıkım, havaya uçurma'), ('fracture', 'kırmak, çatlatmak'), ('concussion', 'sarsıntı, şok dalgası'), ('obstinate', 'inatçı, dik kafalı')], 'sentences': [{'id': 421, 'text': 'My uncle stared at the enormous barrier with eyes burning with fierce obstinacy.', 'translation': 'Amcam, şiddetli bir inatçılıkla yanan gözlerle devasa engele dik dik baktı.', 'notes': 'fierce obstinacy: şiddetli inatçılık.'}, {'id': 422, 'text': '"Neither granite nor iron will stop us now!" he declared, striking the barrier with his fist.', 'translation': 'Yumruğuyla engele vurarak, "Şimdi ne granit ne de demir bizi durdurabilir!" diye ilan etti.', 'notes': 'striking barrier with fist: yumruğuyla engele vurarak.'}, {'id': 423, 'text': '"We have survived hunger, monsters, and tempests; we shall not surrender to a mere lump of stone!"', 'translation': '"Açlıktan, canavarlardan ve kasırgalardan sağ çıktık; sadece bir taş parçasına boyun eğmeyeceğiz!"', 'notes': 'surrender to a stone: bir taşa teslim olmak / boyun eğmek.'}, {'id': 424, 'text': 'He decided that we would shatter the monolithic obstruction using our remaining kegs of gunpowder.', 'translation': 'Kalan barut fıçılarımızı kullanarak o yekpare engeli paramparça edeceğimize karar verdi.', 'notes': 'shatter monolithic obstruction: yekpare engeli parçalamak.'}, {'id': 425, 'text': 'Hans retrieved his pickaxe and an iron drill from our salvaged supplies on the shore.', 'translation': 'Hans, sahildeki kurtarılmış malzemelerimizden kazmasını ve bir demir matkabı getirdi.', 'notes': 'salvaged supplies: kurtarılan malzemeler.'}, {'id': 426, 'text': 'For six grueling hours, the tireless guide bored a deep borehole into the heart of the granite boulder.', 'translation': 'Altı zorlu saat boyunca yorulmak bilmez rehber, granit kayanın kalbine doğru derin bir delik açtı.', 'notes': 'tireless guide: yorulmak bilmez rehber.'}, {'id': 427, 'text': 'When the cavity reached a depth of over three feet, we packed it tightly with fifty pounds of gunpowder.', 'translation': 'Boşluk üç fiti aşkın bir derinliğe ulaştığında, içini elli libre barutla sıkıca doldurduk.', 'notes': 'packed tightly: sıkıca doldurduk.'}, {'id': 428, 'text': 'We tamped the opening with clay and inserted a long linen fuse soaked in saltpeter.', 'translation': 'Ağzını kille tıkadık ve güherçileye batırılmış uzun bir keten fitil yerleştirdik.', 'notes': 'linen fuse soaked in saltpeter: güherçileye batırılmış keten fitil.'}, {'id': 429, 'text': "The detonation was scheduled for six o'clock on the morning of the twenty-seventh of August.", 'translation': 'Patlama, 27 Ağustos sabahı saat altı için planlandı.', 'notes': 'scheduled for detonation: patlama için planlandı.'}, {'id': 430, 'text': 'To ensure our safety from flying debris, we resolved to wait aboard the raft anchored a hundred yards offshore.', 'translation': 'Uçuşan taş parçalarından güvenliğimizi sağlamak için kıyıdan yüz yarda açıkta demirlemiş salın üzerinde beklemeye karar verdik.', 'notes': 'flying debris: uçuşan taş parçaları / döküntüler.'}, {'id': 431, 'text': 'At precisely a quarter to six, Hans stepped ashore and ignited the end of the long match.', 'translation': 'Tam saat altıya çeyrek kala Hans kıyıya çıktı ve uzun fitilin ucunu ateşledi.', 'notes': 'ignited the end: ucunu ateşledi.'}, {'id': 432, 'text': 'He sprinted back to the beach, leaped aboard the raft, and shoved our craft vigorously out into the deep water.', 'translation': 'Kumsala doğru koştu, sala atladı ve teknemizi kuvvetle derin sulara doğru itti.', 'notes': 'shoved vigorously: kuvvetle itti.'}, {'id': 433, 'text': 'We sat together on the wooden timbers, watching the tiny red spark hiss along the dark cliff.', 'translation': 'Koyu renk uçurum boyunca tıslayarak ilerleyen minik kırmızı kıvılcımı izleyerek ahşap kerestelerin üzerinde yan yana oturduk.', 'notes': 'tiny red spark hiss: minik kırmızı kıvılcımın tıslaması.'}, {'id': 434, 'text': 'The fuse was calculated to burn for exactly ten minutes before reaching the explosive chamber.', 'translation': 'Fitilin patlayıcı hazneye ulaşmadan önce tam on dakika boyunca yanacağı hesaplanmıştı.', 'notes': 'explosive chamber: patlayıcı haznesi.'}, {'id': 435, 'text': 'My uncle held his chronometer in his hand, counting down the seconds with suppressed agitation.', 'translation': 'Amcam bastırılmış bir heyecanla saniyeleri geri sayarak kronometresini elinde tuttu.', 'notes': 'counting down seconds: saniyeleri geri saymak.'}, {'id': 436, 'text': '"One minute more... thirty seconds... fifteen... five..." he whispered through clenched teeth.', 'translation': 'Kenetlenmiş dişlerinin arasından, "Bir dakika kaldı... otuz saniye... on beş... beş..." diye fısıldadı.', 'notes': 'through clenched teeth: kenetlenmiş dişlerinin arasından.'}, {'id': 437, 'text': 'At zero, a momentary, terrifying silence hung over the dark subterranean sea.', 'translation': 'Sıfırda, karanlık yeraltı denizinin üzerine anlık, korkunç bir sessizlik çöktü.', 'notes': 'momentary silence hung: anlık bir sessizlik çöktü.'}, {'id': 438, 'text': 'Then, the solid granite wall of the cliff seemed to rip open from top to bottom.', 'translation': 'Ardından uçurumun sert granit duvarı tepeden tırnağa yırtılıp açılıyor gibi oldu.', 'notes': 'rip open from top to bottom: tepeden tırnağa yırtılıp açılmak.'}, {'id': 439, 'text': 'A flash of incandescent flame turned the subterranean twilight into blinding white daylight.', 'translation': 'Akkor bir alev çakması yeraltı alacakaranlığını kör edici beyaz bir gün ışığına çevirdi.', 'notes': 'incandescent flame: akkor alev.'}, {'id': 440, 'text': 'A concussion so immense that it felt like the entire planet was shattering struck our ears with colossal force.', 'translation': 'Bütün gezegen parçalanıyormuş gibi hissettiren o kadar muazzam bir sarsıntı kulaklarımıza devasa bir kuvvetle çarptı.', 'notes': 'concussion struck ears: sarsıntı kulaklara çarptı.'}]}, {'page_no': 23, 'title': 'The Abyss Swallows the Sea and the Raft', 'tr_title': 'Açılan Uçurumun Denizi Yutması ve Salın Boşluğa Sürüklenişi', 'vocab_focus': [('chasm', 'derin yarık, uçurum'), ('vortex', 'girdap, anafor'), ('cataclysm', 'büyük felaket, tufan'), ('cataract', 'büyük çağlayan, çavlan'), ('swallow', 'yutmak'), ('vertiginous', 'baş döndürücü'), ('plunge', 'dalmak, hızla düşmek'), ('inevitable', 'kaçınılmaz')], 'sentences': [{'id': 441, 'text': 'The explosion did far more than simply shatter the granite boulder barring the gallery.', 'translation': 'Patlama galeriyi tıkayan granit kayayı parçalamaktan çok daha fazlasını yaptı.', 'notes': 'far more than: ...den çok daha fazlası.'}, {'id': 442, 'text': 'It ruptured the entire foundational shelf holding back the waters of the subterranean ocean.', 'translation': 'Yeraltı okyanusunun sularını tutan tüm temel taban sahanlığını yırttı.', 'notes': 'ruptured the foundational shelf: temel tabanı yırttı.'}, {'id': 443, 'text': 'A colossal chasm opened behind the destroyed doorway, plunging straight down into an infinite, bottomless abyss.', 'translation': 'Yıkılan kapının ardında sonsuz, dipsiz bir uçuruma doğru dimdik inen devasa bir yarık açıldı.', 'notes': 'bottomless abyss: dipsiz uçurum.'}, {'id': 444, 'text': 'The entire Central Sea, millions of tons of water, began pouring into this colossal crack like a monstrous Niagara.', 'translation': "Milyonlarca ton sudan oluşan Merkez Denizi'nin tamamı, canavarca bir Niagara gibi bu devasa çatlağın içine akmaya başladı.", 'notes': 'pouring into colossal crack: devasa çatlağın içine akmaya başlayan.'}, {'id': 445, 'text': 'An irresistible aquatic current seized our raft, dragging it violently toward the roaring vortex.', 'translation': 'Karşı konulmaz bir su akıntısı salımızı yakaladı ve kükreyen girdaba doğru şiddetle sürükledi.', 'notes': 'irresistible aquatic current: karşı konulmaz su akıntısı.'}, {'id': 446, 'text': '"Hold fast to the ropes!" my uncle screamed above the deafening cataclysm.', 'translation': 'Sağır edici felaketin üzerinde amcam, "İplere sımsıkı tutunun!" diye çığlık attı.', 'notes': 'hold fast to ropes: iplere sımsıkı tutunmak.'}, {'id': 447, 'text': 'Hans, with miraculous agility, threw himself over our remaining provisions and strapped us to the timbers.', 'translation': 'Hans mucizevi bir çeviklikle kalan erzakımızın üzerine atıldı ve bizi kerestelere bağladı.', 'notes': 'miraculous agility: mucizevi çeviklik.'}, {'id': 448, 'text': 'A terrifying liquid mountain carried our craft to the very edge of the opening.', 'translation': 'Korkunç bir sıvı dağ, teknemizi yarığın tam kenarına kadar taşıdı.', 'notes': 'terrifying liquid mountain: korkunç sıvı dağ.'}, {'id': 449, 'text': 'For one breathless second, the raft hung suspended in midair over the black gulf.', 'translation': 'Nefes kesici bir saniye boyunca sal, kara boşluğun üzerinde havada asılı kaldı.', 'notes': 'hung suspended in midair: havada asılı kaldı.'}, {'id': 450, 'text': 'Then, we plummeted downward with dizzying, vertiginous velocity into the belly of the planet.', 'translation': 'Ardından baş döndürücü bir hızla gezegenin karnına doğru aşağıya fırladık.', 'notes': 'plummeted downward: aşağıya doğru çakıldı / fırladı.'}, {'id': 451, 'text': 'We were not merely falling; we were riding the crest of an underground cataract of unimaginable magnitude.', 'translation': 'Yalnızca düşmüyorduk; hayal bile edilemez büyüklükteki bir yeraltı çavlanının tepesinde sürükleniyorduk.', 'notes': 'riding the crest: tepesinde sürüklenmek.'}, {'id': 452, 'text': 'The wind tore at our clothes, and the rushing water roared like thousands of cannons firing simultaneously.', 'translation': 'Rüzgar giysilerimizi parçalarcasına savuruyor ve akan su aynı anda ateşlenen binlerce top gibi kükrüyordu.', 'notes': 'cannons firing simultaneously: aynı anda ateşlenen toplar.'}, {'id': 453, 'text': 'All light disappeared instantly as we were swallowed by a vertical tunnel of solid rock.', 'translation': 'Sert kayadan dikey bir tünel tarafından yutulduğumuz anda tüm ışık anında kayboldu.', 'notes': 'swallowed by vertical tunnel: dikey tünelce yutuldu.'}, {'id': 454, 'text': 'We clung to each other in the darkness, soaked, bruised, and convinced that our end had arrived.', 'translation': 'Sırılsıklam, ezik içinde ve sonumuzun geldiğine inanmış bir halde karanlıkta birbirimize sarıldık.', 'notes': 'convinced that end arrived: sonun geldiğine inanmış.'}, {'id': 455, 'text': 'Hour after hour, the furious torrent hurled our wooden craft deeper and deeper into the Earth.', 'translation': "Saatler boyunca azgın çağlayan ahşap teknemizi Dünya'nın daha ve daha derinlerine fırlattı.", 'notes': 'hurled craft deeper: tekneyi daha derine fırlattı.'}, {'id': 456, 'text': 'My breath was forced back into my throat by the immense atmospheric pressure building around us.', 'translation': 'Etrafımızda biriken muazzam atmosferik basınç nedeniyle nefesim boğazıma geri tıkandı.', 'notes': 'breath forced back into throat: nefesi boğazına tıkandı.'}, {'id': 457, 'text': 'How many leagues were we falling? Were we plunging directly toward the fiery molten core of the globe?', 'translation': 'Kaç fersah boyunca düşüyorduk? Yerkürenin akkor halindeki erimiş çekirdeğine dosdoğru mu dalıyorduk?', 'notes': 'plunging directly toward: dosdoğru ...e dalan.'}, {'id': 458, 'text': 'No human mind could calculate our trajectory through this roaring abyss of darkness.', 'translation': 'Hiçbir insan zihni bu kükreyen karanlık uçurumdaki yörüngemizi hesaplayamazdı.', 'notes': 'calculate trajectory: yörüngeyi hesaplamak.'}, {'id': 459, 'text': 'I lost all sense of time, space, and reality, floating between life and eternal oblivion.', 'translation': 'Yaşam ile ebedi unutuluş arasında süzülerek tüm zaman, mekan ve gerçeklik algımı kaybettim.', 'notes': 'eternal oblivion: ebedi unutuluş / yokluk.'}, {'id': 460, 'text': 'Only the iron grip of Hans on my collar kept my limp body from slipping into the watery grave.', 'translation': "Yalnızca Hans'ın yakamdaki demir gibi tutuşu halsiz bedenimin sulu bir mezara kayıp gitmesini engelledi.", 'notes': 'watery grave: sulu mezar.'}]}, {'page_no': 24, 'title': 'The Rising Column of Boiling Magma', 'tr_title': 'Yükselen Lav Dalgası: Aktif Bir Yanardağ Bacasından Yukarı Fırlayış', 'vocab_focus': [('eruption', 'püskürme, patlama'), ('magma', 'magma, erimiş kaya'), ('incandescent', 'akkor, akkor halinde'), ('scaffolding', 'iskele, destek yapısı'), ('ascent', 'yükseliş, yukarı çıkış'), ('suffocating', 'boğucu, nefes kesici'), ('thermometer', 'termometre'), ('upward', 'yukarı doğru')], 'sentences': [{'id': 461, 'text': 'After what seemed like an eternity of plunging, the furious downward velocity of our raft began to decelerate.', 'translation': 'Sonsuzluk gibi gelen bir düşüşün ardından salımızın azgın aşağı yönlü hızı yavaşlamaya başladı.', 'notes': 'began to decelerate: yavaşlamaya başladı.'}, {'id': 462, 'text': 'The roaring cataract struck a subterranean reservoir, and the water level began to rise beneath our timbers.', 'translation': 'Kükreyen çavlan bir yeraltı su haznesine çarptı ve su seviyesi kerestelerimizin altında yükselmeye başladı.', 'notes': 'subterranean reservoir: yeraltı haznesi / sarnıcı.'}, {'id': 463, 'text': 'Suddenly, I realized with a jolt of shock that we were no longer falling; we were rising rapidly!', 'translation': 'Aniden bir şok sarsıntısıyla artık düşmediğimizi, hızla yükseldiğimizi fark ettim!', 'notes': 'jolt of shock: şok sarsıntısı.'}, {'id': 464, 'text': '"Uncle! Look! The water is carrying us upward!" I shouted, rubbing my salt-crusted eyes.', 'translation': 'Tuz bağlamış gözlerimi ovuşturarak, "Amca! Bak! Su bizi yukarıya doğru taşıyor!" diye bağırdım.', 'notes': 'carrying us upward: bizi yukarı taşıyor.'}, {'id': 465, 'text': 'My uncle lit a torch and examined the narrow vertical shaft enclosing our craft.', 'translation': 'Amcam bir meşale yaktı ve teknemizi çevreleyen dar dikey bacayı inceledi.', 'notes': 'narrow vertical shaft: dar dikey baca.'}, {'id': 466, 'text': 'We were trapped inside an immense volcanic chimney, propelled upward like a piston inside a cylinder.', 'translation': 'Bir silindirin içindeki piston gibi yukarı doğru itilerek devasa bir volkanik bacanın içinde kapana kısılmıştık.', 'notes': 'piston inside a cylinder: silindirin içindeki piston.'}, {'id': 467, 'text': 'Even more alarming, the temperature of the water around us was increasing at a terrifying rate.', 'translation': 'Daha da korkutucu olanı, etrafımızdaki suyun sıcaklığı korkunç bir hızla artıyordu.', 'notes': 'increasing at a terrifying rate: korkunç bir hızla artıyordu.'}, {'id': 468, 'text': 'Dense clouds of white steam filled the shaft, making it almost impossible to draw breath.', 'translation': 'Yoğun beyaz buhar bulutları bacayı doldurdu, nefes almayı neredeyse imkansız hale getirdi.', 'notes': 'draw breath: nefes almak.'}, {'id': 469, 'text': '"The water has met subterranean fires!" the professor shouted, his voice shaking with awe.', 'translation': 'Profesör sesi huşuyla titreyerek, "Su yeraltı ateşleriyle buluştu!" diye bağırdı.', 'notes': 'subterranean fires: yeraltı ateşleri.'}, {'id': 470, 'text': '"The ocean that poured into the chasm is being converted into superheated steam!"', 'translation': '"Yarığın içine dökülen okyanus aşırı ısınmış buhara dönüştürülüyor!"', 'notes': 'superheated steam: aşırı ısınmış buhar.'}, {'id': 471, 'text': 'Beneath the boiling water, a glowing mass of liquid red magma was expanding with explosive volcanic pressure.', 'translation': 'Kaynar suyun altında sıvı kızıl magmadan oluşan akkor bir kütle, patlayıcı volkanik basınçla genleşiyordu.', 'notes': 'liquid red magma: sıvı kızıl magma.'}, {'id': 472, 'text': 'We were caught in the throat of an active volcano in the middle of a full-scale eruption!', 'translation': 'Geniş çaplı bir püskürmenin tam ortasında aktif bir yanardağın boğazında yakalanmıştık!', 'notes': 'full-scale eruption: geniş çaplı püskürme / patlama.'}, {'id': 473, 'text': '"We are going to be boiled alive or incinerated by lava!" I wept in total despair.', 'translation': 'Tam bir çaresizlikle ağlayarak, "Canlı canlı haşlanacağız ya da lav tarafından küle çevrileceğiz!" dedim.', 'notes': 'incinerated by lava: lav tarafından küle çevrilmiş.'}, {'id': 474, 'text': '"Courage, Axel!" cried the professor, his eyes shining with scientific triumph.', 'translation': 'Gözleri bilimsel bir zaferle parıldayan profesör, "Cesur ol Axel!" diye haykırdı.', 'notes': 'courage, Axel: cesur ol Axel.'}, {'id': 475, 'text': '"This eruption is our only chance of returning to the surface of the living world!"', 'translation': '"Bu püskürme, yaşayan dünyanın yüzeyine dönmek için tek şansımız!"', 'notes': 'surface of the living world: yaşayan dünyanın yüzeyi.'}, {'id': 476, 'text': 'The thermometer climbed rapidly: one hundred degrees, one hundred and twenty, then one hundred and fifty!', 'translation': 'Termometre hızla tırmandı: yüz derece, yüz yirmi, ardından yüz elli!', 'notes': 'thermometer climbed: termometre tırmandı / yükseldi.'}, {'id': 477, 'text': 'We cast off our heavy woolen coats, gasping for air and pouring cooler water over our burning heads.', 'translation': 'Nefes nefese kalarak ve yanan başlarımızın üzerine daha serin sular dökerek kalın yün ceketlerimizi fırlatıp attık.', 'notes': 'gasping for air: nefes almaya çabalayarak.'}, {'id': 478, 'text': 'The raft was rising at the speed of a cannonball, vibrating violently against the smooth chimney walls.', 'translation': 'Sal bir gülle hızıyla yükseliyor, pürüzsüz baca duvarlarına karşı şiddetle sarsılıyordu.', 'notes': 'speed of a cannonball: gülle hızıyla.'}, {'id': 479, 'text': 'A terrifying roar shook the mountain as rivers of liquid fire surged directly behind our floating timbers.', 'translation': 'Sıvı ateş nehirleri yüzen kerestelerimizin hemen ardından kabarırken korkunç bir kükreme dağı sarstı.', 'notes': 'rivers of liquid fire: sıvı ateş nehirleri.'}, {'id': 480, 'text': 'Blinded by the incandescent glare and choked by sulfur fumes, I surrendered to blissful unconsciousness.', 'translation': 'Akkor parıltıdan körleşmiş ve kükürt dumanlarıyla boğulmuş olarak kendimi huzurlu bir baygınlığa bıraktım.', 'notes': 'blissful unconsciousness: huzur verici baygınlık.'}]}, {'page_no': 25, 'title': 'Rebirth Under the Mediterranean Sun on Stromboli', 'tr_title': "Stromboli Adası'nda Akdeniz Güneşi Altında Yeniden Doğuş ve Zafer", 'vocab_focus': [('resurrection', 'yeniden diriliş, dirilme'), ('azure', 'masmavi, gök mavisi'), ('mediterranean', "Akdeniz, Akdeniz'e ait"), ('vineyard', 'üzüm bağı'), ('olive', 'zeytin'), ('celebrated', 'ünlü, meşhur'), ('triumphant', 'zafer dolu, muzaffer'), ('immortal', 'ölümsüz')], 'sentences': [{'id': 481, 'text': 'When my eyelids slowly fluttered open, a blinding golden radiance greeted my astonished vision.', 'translation': 'Göz kapaklarım yavaşça aralandığında, kör edici altın bir ışıltı şaşkın bakışlarımı selamladı.', 'notes': 'eyelids slowly fluttered open: göz kapakları yavaşça aralandı.'}, {'id': 482, 'text': 'It was not the pale electrical glow of the subterranean world, but the glorious, warm sunshine of our Earth.', 'translation': 'Yeraltı dünyasının soluk elektriksel ışıltısı değil, Dünyamızın şanlı, sıcacık güneş ışığıydı bu.', 'notes': 'warm sunshine: sıcacık güneş ışığı.'}, {'id': 483, 'text': 'I was lying upon a soft bed of green grass, inhaling the sweet fragrance of blooming flowers and wild herbs.', 'translation': 'Açan çiçeklerin ve yabani otların tatlı kokusunu içime çekerek yeşil çimenden yumuşak bir yatakta yatıyordum.', 'notes': 'sweet fragrance of blooming flowers: açan çiçeklerin tatlı kokusu.'}, {'id': 484, 'text': 'Beside me sat my uncle and Hans, their faces blackened with volcanic soot but completely unharmed.', 'translation': 'Yanımda amcam ve Hans oturuyordu; yüzleri volkanik isle kararmıştı ama tamamen yarasızdılar.', 'notes': 'blackened with soot: isle kararmış.'}, {'id': 485, 'text': '"Axel! We are saved!" my uncle exclaimed, embracing me with overflowing happiness.', 'translation': 'Taşan bir mutlulukla bana sarılarak amcam, "Axel! Kurtulduk!" diye haykırdı.', 'notes': 'overflowing happiness: taşan mutluluk.'}, {'id': 486, 'text': 'The eruption had catapulted us through the smoking crater of a volcano and landed us gently on this grassy slope.', 'translation': 'Püskürme bizi bir yanardağın tüten kraterinden yukarı fırlatmış ve bu çimenli yamaca nazikçe kondurmuştu.', 'notes': 'catapulted us through: ...den yukarı fırlattı.'}, {'id': 487, 'text': '"Are we back in Iceland?" I asked, looking around at the lush vegetation and azure sea.', 'translation': 'Gür bitki örtüsüne ve masmavi denize bakınarak, "İzlanda\'ya mı döndük?" diye sordum.', 'notes': 'lush vegetation: gür bitki örtüsü.'}, {'id': 488, 'text': '"Look at those olive groves and terraced vineyards!" laughed the professor.', 'translation': 'Profesör gülerek, "Şu zeytinliklere ve taraçalı üzüm bağlarına bak!" dedi.', 'notes': 'terraced vineyards: taraçalı üzüm bağları.'}, {'id': 489, 'text': '"We entered the Earth through the frozen craters of the Arctic, and we have emerged in the warm Mediterranean!"', 'translation': '"Dünya\'ya Kuzey Kutbu\'nun donmuş kraterlerinden girdik ve sıcak Akdeniz\'den çıktık!"', 'notes': "emerged in warm Mediterranean: sıcak Akdeniz'de ortaya çıktık."}, {'id': 490, 'text': 'A young local peasant boy approached us, staring with wide eyes at our scorched clothing and blackened faces.', 'translation': 'Yanık giysilerimize ve kararmış yüzlerimize iri gözlerle bakan yerli genç bir köylü çocuğu bize yaklaştı.', 'notes': 'staring with wide eyes: koca gözlerle bakan.'}, {'id': 491, 'text': 'In response to my uncle\'s questions in Italian, the boy smiled and replied: "Stromboli!"', 'translation': 'Amcamın İtalyanca sorularına karşılık çocuk gülümsedi ve yanıtladı: "Stromboli!"', 'notes': 'in response to questions: sorulara cevaben.'}, {'id': 492, 'text': 'We were standing on the volcanic island of Stromboli, off the sun-drenched coast of Sicily!', 'translation': "Sicilya'nın güneşle yıkanan kıyılarının açıklarındaki volkanik Stromboli Adası'nda duruyorduk!", 'notes': 'sun-drenched coast: güneşle yıkanan sahil.'}, {'id': 493, 'text': 'In three extraordinary months, we had traversed over three thousand miles beneath the crust of Europe.', 'translation': 'Üç olağanüstü ayda, Avrupa kıtasının kabuğu altında üç bin milden fazla mesafe katetmiştik.', 'notes': 'traversed over three thousand miles: üç bin milden fazla yol aştı.'}, {'id': 494, 'text': 'The generous Italian fishermen welcomed us with hearty hospitality, providing delicious wine, fresh bread, and fruit.', 'translation': 'Cömert İtalyan balıkçıları lezzetli şarap, taze ekmek ve meyveler ikram ederek bizi candan bir konukseverlikle karşıladılar.', 'notes': 'hearty hospitality: candan misafirperverlik.'}, {'id': 495, 'text': 'Our return journey to Germany was a continuous triumph across the civilized capitals of Europe.', 'translation': "Almanya'ya dönüş yolculuğumuz, Avrupa'nın medeni başkentleri boyunca kesintisiz bir zafer turu oldu.", 'notes': 'continuous triumph: kesintisiz bir zafer.'}, {'id': 496, 'text': 'In Hamburg, our dear housekeeper Martha wept with joy, having long presumed that we were dead.', 'translation': "Hamburg'da sevgili kahyamız Martha, çoktan öldüğümüzü zannettiği için sevinç gözyaşları döktü.", 'notes': 'wept with joy: sevinçten ağladı.'}, {'id': 497, 'text': 'My beloved Graüben threw her arms around my neck, and within a month our joyful wedding was celebrated.', 'translation': 'Sevgili Graüben kollarını boynuma doladı ve bir ay içinde neşeli düğünümüz kutlandı.', 'notes': 'joyful wedding: neşeli düğün.'}, {'id': 498, 'text': 'Hans, true to his modest northern soul, refused all medals and returned peacefully to his beloved Icelandic eider ducks.', 'translation': 'Mütevazı kuzey ruhuna sadık kalan Hans, tüm madalyaları reddetti ve çok sevdiği İzlanda eider ördeklerine huzur içinde döndü.', 'notes': 'true to modest soul: mütevazı ruhuna sadık.'}, {'id': 499, 'text': 'Professor Otto Lidenbrock was celebrated as one of the greatest scientific explorers in human history.', 'translation': 'Profesör Otto Lidenbrock, insanlık tarihinin en büyük bilimsel kaşiflerinden biri olarak göklere çıkarıldı.', 'notes': 'celebrated as greatest explorer: en büyük kaşif olarak anıldı.'}, {'id': 500, 'text': "And on his desk in Hamburg, beside Saknussemm's ancient runic parchment, our journey to the center of the Earth became immortal.", 'translation': "Ve Hamburg'daki çalışma masasında, Saknussemm'in kadim rünik parşömeninin yanı başında, Dünya'nın merkezine yaptığımız yolculuk ölümsüzleşti.", 'notes': 'became immortal: ölümsüzleşti.'}]}]
